def format_money(amount, minor_units):
    sign = "-" if amount < 0 else ""
    # Zero is never negative
    if amount == 0:
        if minor_units > 0:
            return "0." + "0" * minor_units
        else:
            return "0"

    abs_amount = abs(amount)
    # Use quantize to ensure correct precision
    pattern = Decimal('1.' + '0' * minor_units) if minor_units > 0 else Decimal('1')
    s = "{:,.{}f}".format(abs_amount.quantize(pattern, rounding=ROUND_HALF_EVEN), minor_units)
    return sign + s

def get_quantize_pattern(minor_units):
    if minor_units == 0:
        return Decimal('1')
    return Decimal('1.' + '0' * minor_units)

