import sys
import os
from decimal import Decimal, getcontext, ROUND_HALF_EVEN

def get_pattern(m):
    """Returns a Decimal pattern for quantizing to m minor units."""
    if m == 0:
        return Decimal('1')
    return Decimal('1.' + '0' * m)

def format_money(amount, minor_units):
    """Formats the amount according to the currency's minor units."""
    if amount == 0:
        if minor_units > 0:
            return "0." + "0" * minor_units
        else:
            return "0"

    sign = "-" if amount < 0 else ""
    abs_amount = abs(amount)
    pattern = get_pattern(minor_units)
    # Quantize to ensure correct precision before formatting
    rounded_abs = abs_amount.quantize(pattern, rounding=ROUND_HALF_EVEN)

    # Use string formatting to handle comma-separated integer parts
    s = "{:,.{}f}".format(rounded_abs, minor_units)
    return sign + s

