    directory = sys.argv[1]
    ledger_path = os.path.join(directory, 'ledger.txt')
    if not os.path.exists(ledger_path):
        return

    # Set high precision for exact decimal arithmetic
    getcontext().prec = 100

    accounts = {}  # name -> {'currency': CODE, 'balance': Decimal, 'limit': Decimal}
    currencies = {}  # CODE -> minor_units
    rejections = []

    with open(ledger_path, 'r') as f:
        lines = f.readlines()

    for idx, line in enumerate(lines):
        line_num = idx + 1
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue

        parts = line.split()
        command = parts[0]

        # 1. Check for unknown account / existing account
        names_to_check = []
        if command == 'open':
            names_to_check = [parts[1]]
        elif command in ['deposit', 'withdraw', 'interest']:
            names_to_check = [parts[1]]
        elif command in ['transfer', 'convert']:
            names_to_check = [parts[1], parts[2]]
        elif command == 'split':
            names_to_check = [parts[1]]
            for p in parts[3:]:
                names_to_check.append(p.split(':')[0])

        error_found = False
        for name in names_to_check:
            if command == 'open':
                if name in accounts:
                    rejections.append(f"line {line_num}: REJECT account exists {name}")
                    error_found = True
                    break
            else:
                if name not in accounts:
                    rejections.append(f"line {line_num}: REJECT unknown account {name}")
                    error_found = True
                    break
        if error_found:
            continue

        # 2. Execute command and check rules
        try:
            if command == 'currency':
                currencies[parts[1]] = int(parts[2])
                continue
            elif command == 'open':
                name, code, limit = parts[1], parts[2], Decimal('0')
                if len(parts) > 3:
                    limit = Decimal(parts[3])
                accounts[name] = {'currency': code, 'balance': Decimal('0'), 'limit': limit}
                continue
            elif command == 'deposit':
                name, amount_raw = parts[1], Decimal(parts[2])
                amount = amount_raw.quantize(get_pattern(currencies[accounts[name]['currency']]), rounding=ROUND_HALF_EVEN)
                if amount <= 0:
                    rejections.append(f"line {line_num}: REJECT non-positive amount")
                    continue
                accounts[name]['balance'] += amount
                continue
            elif command == 'withdraw':
                name, amount_raw = parts[1], Decimal(parts[2])
                amount = amount_raw.quantize(get_pattern(currencies[accounts[name]['currency']]), rounding=ROUND_HALF_EVEN)
                if amount <= 0:
                    rejections.append(f"line {line_num}: REJECT non-positive amount")
                    continue
                if accounts[name]['balance'] - amount < -accounts[name]['limit']:
                    rejections.append(f"line {line_num}: REJECT insufficient funds {name}")
                    continue
                accounts[name]['balance'] -= amount
                continue
            elif command == 'transfer':
                from_n, to_n, amount_raw = parts[1], parts[2], Decimal(parts[3])
                amount = amount_raw.quantize(get_pattern(currencies[accounts[from_n]['currency']]), rounding=ROUND_HALF_EVEN)
                if accounts[from_n]['currency'] != accounts[to_n]['currency']:
                    rejections.append(f"line {line_num}: REJECT currency mismatch")
                    continue
                if amount <= 0:
                    rejections.append(f"line {line_num}: REJECT non-positive amount")
                    continue
                if accounts[from_n]['balance'] - amount < -accounts[from_n]['limit']:
                    rejections.append(f"line {line_num}: REJECT insufficient funds {from_n}")
                    continue
                accounts[from_n]['balance'] -= amount
                accounts[to_n]['balance'] += amount
                continue
            elif command == 'convert':
                from_n, to_n, amount_raw, rate = parts[1], parts[2], Decimal(parts[3]), Decimal(parts[4])
                amount = amount_raw.quantize(get_pattern(currencies[accounts[from_n]['currency']]), rounding=ROUND_HALF_EVEN)
                if accounts[from_n]['currency'] != accounts[to_n]['currency']:
                    rejections.append(f"line {line_num}: REJECT currency mismatch")
                    continue
                if amount <= 0:
                    rejections.append(f"line {line_num}: REJECT non-positive amount")
                    continue
                if accounts[from_n]['balance'] - amount < -accounts[from_n]['limit']:
                    rejections.append(f"line {line_num}: REJECT insufficient funds {from_n}")
                    continue
                to_amount = (amount * rate).quantize(get_pattern(currencies[accounts[to_n]['currency']]), rounding=ROUND_HALF_EVEN)
                accounts[from_n]['balance'] -= amount
                accounts[to_n]['balance'] += to_amount
                continue
            elif command == 'interest':
                name, rate = parts[1], Decimal(parts[2])
                interest_amount = (accounts[name]['balance'] * rate).quantize(get_pattern(currencies[accounts[name]['currency']]), rounding=ROUND_HALF_EVEN)
                if accounts[name]['balance'] + interest_amount < -accounts[name]['limit']:
                    rejections.append(f"line {line_num}: REJECT insufficient funds {name}")
                    continue
                accounts[name]['balance'] += interest_amount
                continue
            elif command == 'split':
                from_n, amount_raw = parts[1], Decimal(parts[2])
                amount = amount_raw.quantize(get_pattern(currencies[accounts[from_n]['currency']]), rounding=ROUND_HALF_EVEN)
                if amount <= 0:
                    rejections.append(f"line {line_num}: REJECT non-positive amount")
                    continue

                targets = []
                for p in parts[3:]:
                    t_name, t_weight = p.split(':')
                    targets.append({'name': t_name, 'weight': int(t_weight)})

                # Check currency mismatch (already checked unknown accounts)
                for t in targets:
                    if accounts[from_n]['currency'] != accounts[t['name']]['currency']:
                        rejections.append(f"line {line_num}: REJECT currency mismatch")
                        error_found = True
                        break
                if error_found: continue

                if accounts[from_n]['balance'] - amount < -accounts[from_n]['limit']:
                    rejections.append(f"line {line_num}: REJECT insufficient funds {from_n}")
                    continue

                # Split logic using integer minor units
                minor_units = currencies[accounts[from_n]['currency']]
                A_units = int(amount.scaleb(minor_units).to_integral_value(rounding=ROUND_HALF_EVEN))
                W = sum(t['weight'] for t in targets)

                shares = []
                remainders = []
                for t in targets:
                    s = (A_units * t['weight']) // W
                    r = (A_units * t['weight']) % W
                    shares.append(s)
                    remainders.append(r)

                L = A_units - sum(shares)
                # Sort targets: R_i descending, then index ascending
                sorted_indices = sorted(range(len(targets)), key=lambda i: (-remainders[i], i))
                for i in range(L):
                    shares[sorted_indices[i]] += 1

                # Apply the splits
                accounts[from_n]['balance'] -= amount
                for i, t in enumerate(targets):
                    t_amount = Decimal(shares[i]) / Decimal(10**minor_units)
                    accounts[t['name']]['balance'] += t_amount
                continue
        except Exception:
            pass

    # Final Output
    for r in rejections:
        print(r)
    print()

    sorted_account_names = sorted(accounts.keys())
    for name in sorted_account_names:
        acc = accounts[name]
        print(f"{name} {acc['currency']} {format_money(acc['balance'], currencies[acc['currency']])}")

    print()

    currency_totals = {}
    for name, acc in accounts.items():
        code = acc['currency']
        if code not in currency_totals:
            currency_totals[code] = {'sum': Decimal('0'), 'count': 0}
        currency_totals[code]['sum'] += acc['balance']
        currency_totals[code]['count'] += 1

    sorted_codes = sorted(currency_totals.keys())
    for code in sorted_codes:
        total_data = currency_totals[code]
        print(f"total {code} {format_money(total_data['sum'], currencies[code])} ({total_data['count']} accounts)")

