import * as fs from 'fs';
import * as path from 'path';

function solve() {
    const args = process.argv.slice(2);
    if (args.length === 0) return;
    const dir = args[0];
    const files = fs.readdirSync(dir).filter(f => f.endsWith('.bmp')).sort();

    for (const file of files) {
        const filePath = path.join(dir, file);
        const buffer = fs.readFileSync(filePath);

        const bfOffBits = buffer.readUInt32LE(10);
        const dibSize = buffer.readUInt32LE(14);
        const width = buffer.readInt32LE(18);
        const height = buffer.readInt32LE(22);
        const bpp = buffer.readUInt16LE(28);
        const compression = buffer.readUInt32LE(32);

        console.log(`== ${file}`);
        if (compression !== 0 && compression !== 3) {
            console.log(`error: unsupported compression ${compression}`);
            continue;
        }

        const H = Math.abs(height);
        const W = Math.abs(width);
        const isBottomUp = height > 0;
        const orientation = isBottomUp ? "bottom-up" : "top-down";

        const colorTable: { r: number, g: number, b: number }[] = [];
        const tableOffset = 14 + dibSize;
        const numColors = Math.max(0, Math.floor((bfOffBits - tableOffset) / 4));
        for (let i = 0; i < numColors; i++) {
            const offset = tableOffset + i * 4;
            colorTable.push({ b: buffer[offset], g: buffer[offset + 1], r: buffer[offset + 2] });
        }

        let maskR = 0, maskG = 0, maskB = 0;
        if (compression === 3) {
            const masksOffset = 14 + (dibSize === 40 ? 40 : (dibSize - 16));
            maskB = buffer.readUInt32LE(masksOffset);
            maskG = buffer.readUInt32LE(masksOffset + 4);
            maskR = buffer.readUInt32LE(masksOffset + 8);
        }

        const getMaskInfo = (mask: number) => {
            let s = 0;
            while (s < 32 && !((mask >>> s) & 1)) s++;
            let n = 0;
            let temp = mask;
            while (temp > 0) {
                if (temp & 1) n++;
                temp >>>= 1;
            }
            return { s, n, m: (1 << n) - 1 };
        };

        const maskInfoB = getMaskInfo(maskB);
        const maskInfoG = getMaskInfo(maskG);
        const maskInfoR = getMaskInfo(maskR);

        const isInk = Array.from({ length: H }, () => new Uint8Array(W));
        let totalInk = 0;

        for (let i = 0; i < H; i++) {
            const y_coord = isBottomUp ? (H - 1 - i) : i;
            const rowStart = bfOffBits + i * Math.ceil((W * bpp) / 8);

            for (let x = 0; x < W; x++) {
                let r = 0, g = 0, b = 0;
                if (bpp <= 8) {
                    const byteIdx = Math.floor((x * bpp) / 8);
                    const byteOffset = bfOffBits + i * Math.ceil((W * bpp) / 8) + byteIdx;
                    const byte = buffer[byteOffset];
                    let idx = 0;
                    if (bpp === 1) idx = (byte >> (7 - (x % 8))) & 1;
                    else if (bpp === 4) idx = (x % 2 === 0) ? (byte >> 4) : (byte & 0x0F);
                    else idx = byte;
                    r = colorTable[idx].r; g = colorTable[idx].g; b = colorTable[idx].b;
                } else if (bpp === 24) {
                    const byteOffset = bfOffBits + i * Math.ceil((W * bpp) / 8) + (x * 3);
                    b = buffer[byteOffset]; g = buffer[byteOffset + 1]; r = buffer[byteOffset + 2];
                } else if (bpp === 32) {
                    const byteOffset = bfOffBits + i * Math.ceil((W * bpp) / 8) + (x * 4);
                    if (compression === 0) {
                        b = buffer[byteOffset]; g = buffer[byteOffset + 1]; r = buffer[byteOffset + 2];
                    } else {
                        const pixel = buffer.readUInt32LE(byteOffset);
                        const vB = (pixel & maskB) >>> maskInfoB.s;
                        const vG = (pixel & maskG) >>> maskInfoG.s;
                        const vR = (pixel & maskR) >>> maskInfoR.s;
                        b = Math.floor((vB * 255 + Math.floor(maskInfoB.m / 2)) / maskInfoB.m);
                        g = Math.floor((vG * 255 + Math.floor(maskInfoG.m / 2)) / maskInfoG.m);
                        r = Math.floor((vR * 255 + Math.floor(maskInfoR.m / 2)) / maskInfoR.m);
                    }
                }
                if ((299 * r + 587 * g + 114 * b) / 1000 < 128) {
                    isInk[y_coord][x] = 1;
                    totalInk++;
                }
            }
        }

        console.log(`size ${W}x${H} bpp ${bpp} header ${dibSize} ${orientation} ink ${totalInk}`);

        const visited = Array.from({ length: H }, () => new Uint8Array(W));
        const components: { first: [number, number], bbox: [number, number, number, number], count: number }[] = [];

        for (let y = s_y = 0; y < H; y++) {
            for (let x = 0; x < W; x++) {
                if (isInk[y][x] && !visited[y][x]) {
                    let minX = x, maxX = x, minY = y, maxY = y;
                    let count = 0;
                    const first = [x, y];
                    const queue: [number, number][] = [[x, y]];
                    visited[y][x] = 1;

                    let head = 0;
                    while(head < queue.length) {
                        const [cx, cy] = queue[head++];
                        count++;
                        if (cx < minX) minX = cx;
                        if (cx > maxX) maxX = cx;
                        if (cy < minY) minY = cy;
                        if (cy > maxY) maxY = cy;

                        for (let dy = -1; dy <= s_dy = 1; dy++) {
                            for (let dx = -1; dx <= 1; dx++) {
                                if (dx === 0 && dy === 0) continue;
                                const nx = cx + dx, ny = cy + dy;
                                if (nx >= 0 && nx < W && ny >= 0 && ny < H && isInk[ny][nx] && !visited[ny][nx]) {
                                    visited[ny][nx] = 1;
                                    queue.push([nx, ny]);
                                }

                            }
                        }
                    }
                    // Wait, the first pixel in reading order must be the one with the smallest y, then smallest x.
                    // The current (x, y) is the first-encountered pixel, so it's the smallest y, then smallest x.
                    components.push({ first: [x, y], bbox: [minX, minY, maxX, maxY], count });
                }
            }
        }
        // The BFS above might not correctly identify the "first" pixel if it's not the smallest y, then smallest x.
        // But since we iterate y from 0 to H-1 and x from 0 to W-1, the first pixel we encounter 
        // in an unvisited component will always be the one with the minimum y, then minimum x.

        console.log(`components ${components.length}`);
        for (const comp of components) {
            console.log(`${comp.first[0]},${comp.first[1]} bbox ${comp.bbox[0]},${comp.bbox[1]}-${comp.bbox[2]},${comp.bbox[3]} pixels ${comp.count}`);
        }
    }
}

