/**
 * The program uses BigInt to handle exact decimal arithmetic.
 * All amounts are scaled to 10^20 to ensure sufficient precision.
 * The scale for each currency is handled by rounding to its minor units.
 */

const SCALE = 20n;
const FACTOR = ://
const FACTOR_20 = 10n ** 20n;

interface Account {
    name: string;
    code: string;
    balance: bigint; // in minor units
    limit: bigint;   // in minor units
}

interface Currency {
    code: string;
    minorUnits: number;
}

const currencies: Map<string, Currency> = new Map();
const accounts: Map<string, Account> = new Map();
const rejections: string[] = [];

/**
 * Parses a decimal string into a BigInt with scale 20.
 */
function parseToBigInt(s: string): bigint {
    const parts = s.split('.');
    let integerPart = BigInt(parts[0]);
    let fractionalPartStr = parts[1] || '';

    // Pad or truncate fractional part to 20 digits
    if (fractionalPartStr.length > 20) {
        fractionalPartStr = fractionalPartStr.substring(0, 20);
    } else {
        fractionalPartStr = fractionalPartStr.padEnd(20, '0');
    }

    // Handle negative sign for integer part
    const isNegative = integerPart < 0n;
    const absInteger = isNegative ? -integerPart : integerpart_abs(integerPart);

    // We'll use a more robust parsing
    const sign = s.startsWith('-') ? -1n : 1n;
    const absS = s.startsWith('-') ? s.substring(1) : s;
    const absParts = absS.split('.');
    const absInt = BigInt(absParts[0]);
    let absFrac = absParts[1] || '';
    absFrac = absFrac.padEnd(20, '0').substring(0, 20);

    const combined = absInt * FACTOR_20 + BigInt(absFrac);
    return sign * combined;
}

// Re-implementing parse more cleanly
function parseToBigIntFixed(s: string): bigint {
    const isNegative = s.startsWith('-');
    const absS = isNegative ? s.substring(1) : s;
    const parts = absS.split('.');
    const integerPart = BigInt(parts[0]);
    let fractionalPartStr = parts[1] || '';

    // Scale to 20
    let combined = integerPart * FACTOR_20;
    const fracVal = BigInt(fractionalPartStr.padEnd(20, '0').substring(0, 20));
    combined += fracVal;

    return isNegative ? -combined : combined;
}

function roundHalfEvenToMinorUnits(X: bigint, targetDivisor: bigint): bigint {
    const q = X / targetDivisor;
    const r = X % targetDivisor;
    const absR = r < 0n ? -r : r;
    const absD = targetDivisor < 0n ? -targetDivisor : targetDivisor;

    if (2n * absR < absD) return q;
    if (2n * absR > absD) return (X > 0n ? q + 1n : q - 1n);
    // Exactly halfway
    if (q % 2n === 0n) return q;
    return (X > 0n ? q + 1n : q - 1n);
}

// Helper to get the multiplier for a specific scale
function getDivisor(m: number): bigint {
    return 10n ** BigInt(20 - m);
}

function formatMoney(amount: bigint, m: number): string {
    const isNegative = amount < 0n;
    let absAmount = isNegative ? -amount : amount;

    // Scale to m
    const divisor = 10n ** BigInt(20 - m);
    // Wait, the amount is already in minor units (scale m).
    // But the input scale was 20. Let's assume amount passed is in scale 20.
    // No, the amount passed to formatMoney should be the value in scale 0 (integer) 
    // but scaled by 10^m.
