function formatIntegerWithCommasFixed(s: string): string {
    // Remove leading zeros but keep one if it's just '0'
    let stripped = s.replace(/^0+/, '');
    if (stripped === '') stripped = '0';

    const len = stripped.length;
    if (len <= 3) return stripped;

    const groups = [];
    for (let i = len; i > 0; i -= 3) {
        const start = Math.max(0, i - 3);
        groups.push(stripped.substring(start, i));
    }
    return groups.reverse().join(',');
