                        let idx = if bpp == 1 { (byte_val >> (7 - (x % 8))) & 1 } else { (byte_val >> (4 * (1 - (x % 2)))) & 0xF };
                        b = data[color_table_start + idx * 4];
                        g = data[color_table_start + idx * 4 + 1];
                        r = data[color_table_start + idx * 4 + 2];
                    }
                } else if bpp == 24 {
                    b = data[row_start + x * 3];
                    g = data[row_start + x * 3 + 1];
                    r = data[row_start + x * 3 + 2];
                } else if bpp == 32 && compression == 0 {
                    b = data[row_start + x * 4];
                    g = data[row_start + x * 4 + 1];
                    r = data[row_start + x * 4 + 2];
                } else if bpp == 32 && compression == 3 {
                    let pixel_val = u32::from_le_bytes(data[row_start + x * 4..row_start + x * 4 + 4].try_into().unwrap());
