                        if mask == 0 { 0 } else {
                            let s = mask.trailing_zeros();
                            let n = mask.count_ones();
                            let v = (val & mask) >> s;
                            let m = (1u32 << n) - 1;
                            ((v * 255 + m / 2) / m) as u8
                        }
                    };
                    r = scale(red_mask, pixel_val);
                    g = scale(green_mask, pixel_val);
                    b = scale(blue_mask, pixel_val);
                }

                if (299 * r as u32 + 587 * g as u32 + 114 * b as u32) / 1000 < 128 {
                    is_ink_grid[y_display][x] = true;
                }
            }
        }

        // Calculate total ink pixels for the header
        let mut total_ink = 0;
        for y in 0..abs_height as usize {
            for x in 0..(width as usize) {
                if is_ink_grid[y][x] {
                    total_ink += 1;
                }
            }
        }

        let orientation = if height > 0 { "bottom-up" } else { "top-down" };
        println!("size {}x{} bpp {} header {} {} ink {}", width, abs_height, bpp, dib_size, orientation, total_ink);

        // Find components
        let mut visited = vec![vec![false; width as usize]; abs_height as usize];
        let mut components = Vec::new();

        for y in  while_y_loop(abs_height) {
            for x in 0..(width as usize) {
                if is_ink_grid[y][x] && !visited[y][x] {
                    let mut comp_pixels = Vec::new();
                    let mut q = vec![(x, y)];
                    visited[y][x] = true;
                    let mut head = 0;
                    while head < q.len() {
                        let (cx, cy) = q[head];
                        head += 1;
                        comp_pixels.push((cx, cy));
                        for dy in -1..=1 {
                            for dx in -1..=1 {
                                if dx == 0 && dy == 0 { continue; }
                                let nx = cx as i32 + dx;
                                let ny = cy as i32 + dy;
                                if nx >= 0 && nx < width && ny >= 0 && ny < abs_height {
                                    let nx = nx as usize;
                                    let ny = ny as usize;
                                    if is_ink_grid[ny][nx] && !visited[ny][nx] {
                                        visited[ny][nx] = true;
                                        q.push((nx, ny));
                                    }
                                }
                            }
                        }
                    }

                    // Find the first pixel in reading order (min y, then min x)
                    let mut first_pixel = (999999, 999999);
                    let mut min_x = 999999;
                    let mut min_y = 999999;
                    let mut max_x = -1;
