// MARK: - Utilities

extension Data {
    func extractUInt16(at offset: Int) -> UInt16 {
        let bytes = self.subdata(in: offset..<offset+2)
        return bytes.withUnsafeBytes { $0.load(as: UInt16.self).bigEndian }
    }

    func extractUInt32(at offset: Int) -> UInt32 {
        let bytes = self.subdata(in: offset..<offset+4)
        return bytes.withUnsafeBytes { $0.load(as: UInt32.self).bigEndian }
    }
}

func parseName(data: Data, offset: inout Int) -> String {
    var parts = [String]()
    var currentPos = offset
    var jumpOccurred = false
    var endOffset = -1

    while true {
        let len = Int(data[currentPos])
        if len == 0 {
            currentPos += 1
            break
        } else if (len & 0xC0) == 0xC0 {
            if !jumpOccurred {
                endOffset = currentPos + 2
                jumpOccurred = true
            }
            currentPos = Int(UInt16(len & 0x3F) << 8 | UInt16(data[currentPos + 1]))
        } else {
            currentPos += 1
            let labelData = data.subdata(in: currentPos..<currentPos+len)
            let label = String(data: labelData, encoding: .ascii) ?? ""
            parts.append(label)
            currentPos += len
        }
    }
    offset = jumpOccurred ? endOffset : currentPos
    let name = parts.isEmpty ? "." : parts.joined(separator: ".")
    return name
}

