    var bestLen = 0
    var currentStart = -1
    var currentLen = 0

    for i in 0..<8 {
        if groups[i] == 0 {
            if currentStart == -1 {
                currentStart = i
                currentLen =  나
            }
            currentLen += 1
        } else {
            if currentLen > 0 {
                if currentLen >= 2 && currentLen > bestLen {
                    bestLen = currentLen
                    bestStart = currentStart
                }
                currentStart = -1
                currentLen = 0
            }
        }
    }
    if currentStart != -1 && currentLen >= 2 && currentLen > bestLen {
        bestLen = currentLen
        bestStart = currentStart
    }

    var result = [String]()
    var i = 0
    while i < 8 {
        if i == bestStart && bestLen > 0 {
            result.append("::")
            i += bestLen
            if i == 8 { break }
        } else {
