    let dir = args[1]
    let port = Int(args[2]) ?? 0

    let queryFile = (dir as NSString).appendingPathComponent("queries.txt")
    guard let content = try? String(contentsOfFile: queryFile) else { return }

    let lines = content.components(separatedBy: .newlines)

    for line in lines {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.isEmpty { continue }

        let parts = trimmed.components(separatedBy: .whitespaces)
        guard parts.count >= 2 else { continue }
        let qName = parts[0]
        let qTypeStr = parts[1]

        var qType: UInt16 = 0
        switch qTypeStr {
        case "A": qType = 1
        case "CNAME": qType = 5
        case "MX": qType = 15
        case "TXT": qType = 16
        case "AAAA": qType = 28
        default: qType = 0
        }

        // Build Query
        var queryData = Data()
        var id = UInt16.random(in: 0...UInt16.max)
        queryData.append(contentsOf: withUnsafeBytes(of: id.bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(0x0100).bigEndian) { Array($0) }) // Flags
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) }) // QDCOUNT
        queryData.append(contentsOf: [0, 0, 0, 0, 0, 0]) // AN, NS, AR counts

        // QNAME
        let labels = qName.trimmingCharacters(in: CharacterSet(charactersIn: ".")).components(separatedBy: ".")
        for label in labels {
            if label.isEmpty { continue }
            let labelBytes = label.data(using: .ascii)!
            queryData.append(UInt8(labelBytes.count))
            queryData.append(labelBytes)
        }
        queryData.append(0)
        queryData.append(contentsOf: withUnsafeBytes(of: qType.bigEndian) { Array($0) })
        queryData.append(contentsOf: withUnsafeBytes(of: UInt16(1).bigEndian) { Array($0) }) // QCLASS=IN

        // UDP Communication
        let fd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
        var addr = sockaddr_in()
        addr.sin_family = UInt8(AF_INET)
        addr.sin_port = UInt16(port).bigEndian
        addrto_inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr)

        _ = withUnsafeMutablePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                sendto(fd, [UInt8](queryData), queryData.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        }

        var responseData = Data()
        var buffer = [UInt8](repeating: 0, count: 65536)

        while true {
            let bytesRead = recv(fd, &buffer, buffer.count, 0)
            if bytesRead > 0 {
                let received = Data(buffer[0..<bytesRead])
