                rdataOutput = target
                offset = rdataStart + rdLength
            case 15: // MX
                let pref = responseData.extractUInt16(at: rdataStart)
                var tempOffset = rdataStart + 2
                let exchange = parseName(data: responseData, offset: &tempOffset)
                typeName = "MX"
                rdataOutput = "\(pref) \(exchange)"
                offset = rdataStart + rdLength
            case 16: // TXT
                var currentPos = rdataStart
                var parts = [String]()
                while currentPos < rdataStart + rdLength {
                    let len = Int(responseData[currentPos])
                    currentPos += 1
                    let labelData = responseData.subdata(in: currentPos..<currentPos+len)
                    currentPos += len

                    var s = "\""
                    for byte in labelData {
                        if byte == 0x22 { s += "\\\"" }
                        else if byte == 0x5C { s += "\\\\" }
                        else if byte >= 0x20 && byte <= 0x7E { s.append(Character(UnicodeScalar(byte))) }
                        else { s += String(format: "\\%03d", byte) }
                    }
                    s += "\""
                    parts.append(s)
                }
                typeName = "TXT"
                rdataOutput = parts.joined(separator: " ")
                offset = rdataStart + rdLength
            default:
                typeName = "TYPE\(type)"
                let hexData = responseData.subdata(in: rdataStart..<rdataStart+rdLength).map { String(format: "%02x", $0) }.joined()
                rdataOutput = "\\# \(rdLength) \(hexData)"
                offset = rdataStart + rdLength
            }

            // Special handling for "other" types if they were not handled
            if rdataOutput == "" && type != 1 && type != 28 && type != 5 && type != 15 && type != 16 {
                let hexData = responseData.subdata(in: rdataStart..<rdataStart+rdLength).map { String(format: "%02x", $0) }.joined()
                rdataOutput = "\\# \(rdLength) \(hexData)"
            }

