func inet_pton_manual(_ af: Int32, _ src: String, _ dst: inout in_addr) {
    let parts = src.components(separatedBy: ".")
    if parts.count == 4, let i1 = UInt32(parts[0]), let i2 = UInt32(parts[1]), let i3 = UInt32(parts[2]), let i4 = UInt32(parts[3]) {
