// MARK: - Helpers

func parseName(data: Data, offset: inout Int) -> String {
    var labels = [String]()
    var currentPos = offset
    var firstJumpOffset = -1

    while true {
        if currentPos >= data.count { break }
        let len = Int(data[currentPos])

        if len == 0 {
            currentPos += 1
            break
        }

        if (len & 0xC0) == 0xC0 {
            if firstJumpOffset == -1 {
                firstJumpOffset = currentPos + 2
            }
            let ptr = Int(UInt16(len & 0x3F) << 8 | UInt16(data[currentPos + 1]))
            currentPos = ptr
        } else {
            currentPos += 1
            let labelData = data.subdata(in: currentPos..<currentPos+len)
            if let label = String(data: labelData, encoding: .ascii) {
                labels.append(label)
            }
            currentPos += len
        }
    }

    if firstJumpOffset != -1 {
        offset = firstJumpOffset
    } else {
        offset = currentPos
    }

    return labels.isEmpty ? "." : labels.joined(separator: ".")
}

func formatIPv6(_ bytes: [UInt8]) -> String {
    var groups = [UInt16]()
    for i in stride(from: 0, to: 16, by: 2) {
        groups.append(UInt16(bytes[i]) << 8 | UInt16(bytes[i+1]))
    }

    var bestStart = -1
    var bestLen = 0
    var currentStart = -1
    var currentLen = 0

    for i in 0..<8 {
        if groups[i] == 0 {
            if currentStart == -1 { currentStart = i }
            currentLen += 1
        } else {
            if currentLen >= 2 && currentLen > bestLen {
                bestLen = currentLen
                bestStart = currentStart
            }
            currentStart = -1
            currentLen = 0
        }
    }
    if currentLen >= 2 && currentLen > bestLen {
        bestLen = currentLen
        bestStart = currentStart
    }

    var result = [String]()
    var i = 0
    while i < 8 {
        if i == bestStart && bestLen > 0 {
            result.append("::")
            i += bestLen
            if i == 8 { break }
        } else {
            result.append(String(format: "%x", groups[i]))
            i += 1
        }
    }

    if bestStart == 0 && bestLen > 0 {
        // If the first group was part of the ::, result[0] is "::". 
        // The joined string will be "::g2:g3...". This is correct.
    }

    return result.joined(separator: ":")
}

