                var tcpBuffer = [UInt8](repeating: 0, count: 65536)
                var tcpData = Data()
                while true {
                    let bytesRead = recv(tcpFd, &tcpBuffer, tcpBuffer.count, 0)
                    if bytesRead <= 0 { break }
                    tcpData.append(contentsOf: tcpBuffer[0..<bytesRead])
                    if tcpData.count >= 2 {
                        let length = tcpData.extractUInt16(at: 0)
                        if tcpData.count >= Int(length) + 2 { break }
                    }
                }
                if tcpData.count >= 2 {
                    let length = tcpData.extractUInt16(at: 0)
                    responseData = tcpData.subdata(in: 2..<Int(length)+2)
                }
                close(tcpFd)
            }
        }

        // Parse Response
        var offset = 0
        let resId = responseData.extractUInt16(at: 0)
        let resFlags = responseData.extractUInt16(at: 2)
        let qdCount = Int(responseData.extractUInt16(at: 4))
        let anCount = Int(responseData.extractUInt16(at: 6))
        let rcodeValue = Int(resFlags & 0x000F)

        let rcodeStrings = ["NOERROR", "FORMERR", "SERVFAIL", "NXDOMAIN", "NOTIMP", "REFUSED"]
        let rcodeStr = rcodeValue < rcodeStrings.count ? rcodeStrings[rcodeValue] : "RCODE\(rcodeValue)"

        print("\(qName.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))) \(qTypeStr.uppercased()) \(rcodeStr)")

        for _ in 0..<qdCount {
            _ = parseName(data: responseData, offset: &offset)
            offset += 4 
        }

        for _ in 0..<anCount {
            let owner = parseName(data: responseData, offset: &offset)
            let type = responseData.extractUInt16(at: offset)
            offset += 2
            let classVal = responseData.extractUInt16(at: offset)
            offset += 2
            let ttl = responseData.extractUInt32(at: offset)
            offset += 4
            let rdLength = Int(responseData.extractUInt16(at: offset))
            offset += 2

            let rdataStart = offset
            var typeName = ""
            var rdataOutput = ""

            switch type {
            case 1: // A
                let ip = "\(responseData[rdataStart]).\(responseData[rdataStart+1]).\(responseData[rdataStart+2]).\(responseData[rdataStart+3])"
                typeName = "A"; rdataOutput = ip
                offset = rdataStart + rdLength
            case 28: // AAAA
                let bytes = Array(responseData.subdata(in: rdataStart..<rdataStart+16))
                typeName = "AAAA"; rdataOutput = formatIPv6(bytes)
                offset = rdataStart + rdLength
            case 5: // CNAME
                var tempOffset = rdataStart
                let target = parseName(data: responseData, offset: &tempOffset)
                typeName = "CNIME" // wait, CNAME
                typeName = "CNAME"; rdataOutput = target
                offset = rdataStart + rdLength
            case 15: // MX
                let pref = responseData.extractUInt16(at: rdataStart)
                var tempOffset = rdataStart + 2
                let exchange = parseName(data: responseData, offset: &tempOffset)
                typeName = "MX"; rdataOutput = "\(pref) \(exchange)"
                offset = rdataStart + rdLength
            case 16: // TXT
                var currentPos = rdataStart
                var parts = [String]()
                while currentPos < rdataStart + rdLength {
                    let len = Int(responseData[currentPos])
                    currentPos += 1
                    let labelData = responseData.subdata(in: currentPos..<currentPos+len)
                    currentPos += len
                    var s = "\""
                    for byte in labelData {
                        if byte == 0x22 { s += "\\\"" }
                        else if byte == 0x5C { s += "\\\\" }
                        else if byte >= 0x20 && byte <= 0x7E { s.append(Character(UnicodeScalar(byte))) }
                        else { s += String(format: "\\%03d", byte) }
                    }
                    s += "\""
                    parts.append(s)
                }
                typeName = "TXT"; rdataOutput = parts.joined(separator: " ")
                offset = rdataStart + rdLength
            default:
                typeName = "TYPE\(type)"
                let hexData = responseData.subdata(in: rdataStart..<rdataStart+rdLength).map { String(format: "%02x", $0) }.joined()
                rdataOutput = "\\# \(rdLength) \(hexData)"
                offset = rdataStart + rdLength
            }

            let ownerPrint = owner.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: ".")) == "" ? "." : owner.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: "."))
            print("  \(ownerPrint) \(ttl) \(typeName) \(rdataOutput)")
        }
    }
}

