fn parse_name(buffer: &[u8], offset: &mut usize) -> Vec<Vec<u8>> {
    let mut labels = Vec::new();
    let mut current_pos = *offset;
    let mut next_offset = None;

    loop {
        if current_pos >= buffer.len() {
            break;
        }
        let len = buffer[current_pos];
        if len == 0 {
            current_pos += 1;
            break;
        }
        if (len & 0xC0) == 0xC0 {
            let pointer = (((len & 0x3F) as usize) << 8) | (buffer[current_pos + 1] as usize);
            if next_offset.is_none() {
                next_offset = Some(current_pos + 2);
            }
            current_pos = pointer;
        } else {
            let label_len = len as usize;
            current_pos += 1;
            if current_pos + label_len <= buffer.len() {
                labels.push(buffer[current_pos..current_pos + label_len].to_vec());
            }
            current_pos += label_len;
        }
    }
    *offset = next_offset.unwrap_or(current_pos);
    labels
}

