fn format_ipv6(addr: Ipv6Addr) -> String {
    let mut groups = [0u16; 8];
    let octets = addr.octets();
    for i in 0..8 {
        groups[i] = u16::from_be_bytes([octets[i * 2], octets[i * 2 + 1]]);
    }

    let mut best_run_start = -1;
    let mut best_run_len = 0;
    let mut current_run_start = -1;
    let mut current_run_len = 0;

    for i in 0..8 {
        if groups[i] == 0 {
            if current_run_len == 0 {
                current_run_start = i as i32;
                current_run_len = 1;
            } else {
                current_run_len += 1;
            }
        } else {
            if current_run_len >= 2 {
                if current_run_len > best_run_len {
                    best_run_len = current_run_len;
                    best_run_start = current_run_start;
                }
            }
            current_run_len = 0;
        }
    }
    if current_run_len >= 2 && current_run_len > best_run_len {
        best_run_len = current_run_len;
        best_run_start = current_run_start;
    }

    let mut result = String::new();
    let mut i = 0;
    while i < 8 {
        if best_run_len >= 2 && i as i32 == best_run_start {
            result.push_str("::");
            i += best_run_len;
            if i == 8 { break; }
        } else {
            result.push_str(&format!("{:x}", groups[i]));
            i += 1;
            if i < 8 && !(best_run_len >= 2 && i as i32 == best_run_start) {
                result.push(':');
            }
        }
    }
    result
}

fn get_labels(buffer: &[u8], offset: &mut usize) -> Vec<Vec<u8>> {
    let mut labels = Vec::new();
    let mut current_i = *offset;
    let mut next_offset = None;

    loop {
        if current_i >= buffer.len() { break; }
        let len = buffer[currents_idx(current_i, buffer)];
        if len == 0 {
            current_i += 1;
            if next_offset.is_none() { next_offset = Some(current_i); }
            break;
        }
        if (len & 0xC0) == 0xC0 {
            let ptr = (((len & 0x3F) as usize) << 8) | (buffer[current_i + 1] as usize);
            if next_offset.is_none() { next_offset = Some(current_i + 2); }

            let mut j = ptr;
            let mut ptr_labels = Vec::new();
            loop {
                let p_len = buffer[j];
                if p_len == 0 {
                    j += 1;
                    break;
                }
                if (p_len & 0xC0) == 0xC0 {
                    j = (((p_len & 0x3F) as usize) << 8) | (buffer[j + 1] as usize);
                } else {
                    let p_label_len = p_len as usize;
                    j += 1;
                    ptr_labels.push(buffer[j..j + p_label_len].to_vec());
                    j += p_label_len;
                }
            }
            labels.extend(ptr_labels);
            break;
        } else {
            let label_len = len as usize;
            current_i += 1;
            labels.push(buffer[current_i..current_i + label_len].to_vec());
            current_i += label_len;
            if next_offset.is_none() {
                // Check if we are at the end of the name
                // The loop continues unless it hits 0 or a pointer.
            }
        }
    }
    *offset = next_offset.unwrap_or(current_i);
    labels
}

