def is_number(v): return isinstance(v, (int, float)) and not isinstance(v, bool)
def is_integer(v): return is_number(v) and v == int(v)
def get_json_type(v):
    if v is None: return "null"
    if isinstance(v, bool): return "boolean"
    if is_number(v): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "object"
    return None
def deep_equal(v1, v2):
    t1, t2 = get_json_type(v1), get_json_type(v2)
    if t1 != t2: return False
    if t1 in ("number", "boolean", "null", "string"): return v1 == v2
    if t1 == "array":
        if len(v1) != len(v2): return False
        for a, b in zip(v1, v2):
            if not deep_equal(a, b): return False
        return True
    if t1 == "object":
        if len(v1) != len(v2): return False
        for k in v1:
            if k not in v2 or not deep_equal(v1[k], v2[k]): return False
        return True
    return False
def get_tokens(pointer):
    if pointer == "#": return []
    path = pointer[1:]
    if not path: return []
    parts = path.split('/')
    if parts[0] == '': parts = parts[1:]
    return [p.replace('~1', '/').replace('~0', '~') for p in parts]
def resolve_ptr(tokens, root_schema):
    curr = root_schema
    for t in tokens:
        if isinstance(curr, dict) and t in curr: curr = curr[t]
        else: return None
    return curr
def get_err_loc(p, k):
    return "#/" + k if p == "#" else p + "/" + k
def matches_type(val, type_name):
    if type_name == "null": return val is None
    if type_name == "boolean": return isinstance(val, bool)
    if type_name == "number": return is_number(val)
    if type_name == "integer": return is_integer(val)
