function base64urlDecode(s: string): Uint8Array | null {
    if (!/^[A-Za-z0-9_-]*$/.test(s)) return null;
    const L = s.length;
    if (L % 4 === 1) return null;
    const bits: number[] = [];
    for (let i = 0; i < L; i++) {
        let val = 0;
        const c = s.charCodeAt(i);
        if (c >= 48 && c <= 57) val = c - 48;
        else if (c >= 65 && c <= 90) val = c - 65 + 26;
        else if (c >= 97 && c <= 122) val = c - 97 + 36;
        else if (c === 45) val = 62;
        else if (c === 95) val = 63;
        for (let j = 5; j >= 0; j--) bits.push((val >> j) & 1);
    }
    const fullBytes = Math.floor((L * 6) / 8);
    for (let i = 8 * fullBytes; i < L * 6; i++) if (bits[i] !== 0) return null;
    const res = new Uint8Array(fullBytes);
    for (let i = 0; i < fullBytes; i++) {
        let byte = 0;
        for (let j = 0; j < 8; j++) byte = (byte << 1) | bits[i * 8 + j];
        res[i] = byte;
    }
    return res;
}

