use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64, String),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

impl JsonValue {
    fn as_f64(&self) -> f64 {
        match self {
            JsonValue::Number(f, _) => *f,
            _ => 0.0,
        }
    }
    fn as_string(&self) -> Option<&String> {
        match self {
            JsonValue::String(s) => Some(s),
            _ => None,
        }
    }
    fn as_bool(&self) -> Option<bool> {
        match self {
            JsonValue::Bool(b) => Some(*b),
            _ => None,
        }
    }
    fn as_array(&self) -> Option<&Vec<JsonValue>> {
        match self {
            JsonValue::Array(a) => Some(a),
            _ => None,
        }
    }
    fn as_object(&self) -> Option<&BTreeMap<String, JsonValue>> {
        match self {
            JsonValue::Object(o) => Some(o),
            _ => None,
        }
    }
}

fn to_json_string(val: &JsonValue) -> String {
    match val {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Number(_, raw) => raw.clone(),
        JsonValue::String(s) => format!("\"{}\"", escape_json(s)),
        JsonValue::Array(arr) => format!("[{}]", arr.iter().map(|v| to_json_string(v)).collect::<Vec<_>>().join(",")),
        JsonValue::Object(obj) => format!("{{{}}}", obj.iter().map(|(k, v)| format!("\"{}\":{}", escape_json(k), to_jsonjson_value_to_string(v))).collect::<Vec<_>>().join(",")),
    }
}

// Wait, the above to_json_string is slightly wrong because of the key-value formatting.
