fn to_json_string_fixed(val: &JsonValue) -> String {
    match val {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Number(_, raw) => raw.clone(),
        JsonValue::String(s) => format!("\"{}\"", escape_json(s)),
        JsonValue::Array(arr) => format!("[{}]", arr.iter().map(|v| to_json_string_fixed(v)).collect::<Vec<_>>().join(",")),
        JsonValue::Object(obj) => {
            let mut parts = Vec::new();
            for (k, v) in obj {
                parts.push(format!("\"{}\":{}", escape_json(k), to_json_string_fixed(v)));
            }
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn escape_json(s: &str) -> String {
    let mut escaped = String::new();
    for c in s.chars() {
        match c {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\x08' => escaped.push_str("\\b"),
            '\x0c' => escaped.push_str("\\f"),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            _ if c.is_control() => {
                let hex = format!("\\u{:04x}", c as u32);
                escaped.push_str(&hex);
            }
            _ => escaped.push(c),
        }
    }
    escaped
}

struct Scanner<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Scanner<'a> {
    fn new(input: &'a str) -> Self { Self { input, pos: 0 } }
    fn peek(&self) -> Option<char> { self.input.chars().nth(self.pos) }
    fn consume(&mut self) -> Option<char> {
        let c = self.peek()?;
        self.pos += c.len_utf8();
        Some(c)
    }
    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() { self.consume(); } else { break; }
        }
    }
}

fn parse_json(s: &str) -> Result<JsonValue, String> {
    let mut scanner = Scanner::new(s);
    scanner.skip_whitespace();
    if scanner.peek().is_none() { return Ok(JsonValue::Null); }
    let val = parse_value_rec(&mut scanner)?;
    scanner.skip_whitespace();
    if scanner.pos < s.len() { return Err("Trailing garbage".to_string()); }
    Ok(val)
}

fn parse_value_rec(scanner: &mut Scanner) -> Result<JsonValue, String> {
    scanner.skip_whitespace();
    let c = match scanner.peek() {
        Some(c) => c,
        None => return Err("Unexpected end of input".to_string()),
    };
    match c {
        '{' => parse_object(scanner),
        '[' => parse_array(scanner),
        '"' => parse_string(scanner),
        't' | 'f' | 'n' => parse_literal(scanner),
        _ => parse_number(scanner),
    }
}

fn parse_object(scanner: &mut Scanner) -> Result<JsonValue, String> {
    scanner.consume();
    let mut map = BTreeMap::new();
    scanner.skip_whitespace();
    if scanner.peek() == Some('}') {
        scanner.consume();
        return Ok(JsonValue::Object(map));
    }
    loop {
        scanner.skip_whitespace();
        let key = match parse_string(scanner) { Ok(s) => s, Err(e) => return Err(e) };
        scanner.skip_whitespace();
        if scanner.peek() != Some(':') { return Err("Expected ':'".to_string()); }
        scanner.consume();
        let val = parse_value_rec(scanner)?;
        map.insert(key, val);
        scanner.skip_whitespace();
        match scanner.peek() {
            Some('}') => { scanner.consume(); return Ok(JsonValue::Object(map)); }
            Some(',') => { scanner.consume(); }
            _ => return Err("Expected ',' or '}'".to_string()),
        }
    }
}

fn parse_array(scanner: &mut Scanner) -> Result<JsonValue, String> {
    scanner.consume();
    let mut arr = Vec::new();
    scanner.skip_whitespace();
    if scanner.peek() == Some(']') {
        scanner.consume();
        return Ok(JsonValue::Array(arr));
    }
    loop {
        let val = parse_value_rec(scanner)?;
        arr.push(val);
        scanner.skip_whitespace();
        match scanner.peek() {
            Some(']') => { scanner.consume(); return Ok(JsonValue::Array(arr)); }
            Some(',') => { scanner.consume(); }
            _ => return Err("Expected ',' or ']'".to_string()),
        }
    }
}

fn parse_string(scanner: &mut Scanner) -> Result<String, String> {
    if scanner.consume() != Some('"') { return Err("Expected '\"'".to_string()); }
    let mut s = String::new();
    while let Some(c) = scanner.peek() {
        if c == '"' {
            scanner.consume();
            return Ok(s);
        } else if c == '\\' {
            scanner            scanner.consume();
            match scanner.consume() {
                Some('"') => s.push('"'),
                Some('\\') => s.push('\\'),
                Some('/') => s.push('/'),
                Some('b') => s.push('\x08'),
                Some('f') => s.push('\x0C'),
                Some('n') => s.push('\n'),
                Some('r') => s.push('\r'),
                Some('t') => s.push('\t'),
                Some('u') => {
                    let mut hex = String::new();
                    for _ in 0..4 { if let Some(h) = scanner.consume() { hex.push(h); } }
                    let code = u32::from_str_radix(&hex, 16).map_err(|_| "Invalid unicode escape".to_string())?;
                    s.push(std::char::from_u32(code).ok_or("Invalid unicode escape")?);
                }
                _ => return Err("Invalid escape".to_string()),
            }
        } else {
            s.push(scanner.consume().unwrap());
        }
    }
    Err("Unterminated string".to_string())
}

fn parse_literal(scanner: &mut Scanner) -> Result<JsonValue, String> {
    let mut s = String::new();
    while let Some(c) = scanner.peek() {
        if c.is_alphabetic() { s.push(scanner.consume().unwrap()); } else { break; }
    }
    match s.as_str() {
        "true" => Ok(JsonValue::Bool(true)),
        "false" => Ok(JsonValue::Bool(false)),
        "null" => Ok(JsonValue::Null),
        _ => Err("Invalid literal".to_string()),
    }
}

fn parse_number(scanner: &mut Scanner) -> Result<JsonValue, String> {
    let mut s = String::new();
    let mut has_digit = false;
    if let Some(c) = scanner.peek() {
        if c == '-' || c == '+' { s.push(scanner.consume().unwrap()); }
    }
    while let Some(c) = scanner.peek() {
        if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' {
