            has_digit = true;
        } else { break; }
    }
    if !has_digit { return Err("Invalid number".to_string()); }
    let val = s.parse::<f64>().map_err(|_| "Invalid number".to_string())?;
    Ok(JsonValue::Number(val, s))
}

fn get_response_id(id_val: &JsonValue) -> JsonValue {
    match id_val {
        JsonValue::String(s) => JsonValue::String(s.clone()),
        JsonValue::Number(_, raw) => {
            if raw.contains('.') || raw.contains('e') || raw.contains('E') {
                JsonValue::Null
            } else {
                JsonValue::Number(id_val.as_f64(), raw.clone())
            }
        }
        _ => JsonValue::Null,
    }
}

