import * as fs from 'fs';
import * as path from 'path';

type ErrorPair = {
  sL: string;
  sP: string;
  L: string[];
  P: string[];
};

function formatPointer(tokens: string[]): string {
  if (tokens.length === 0) return "#";
  return "#/" + tokens.map(t => t.replace(/~/g, "~0").replace(/\//g, "~1")).join("/");
}

function parsePointer(pointer: string): string[] {
  if (pointer === "#" || pointer === "") return [];
  const path = pointer.startsWith("#/") ? pointer.substring(2) : pointer.substring(1);
  if (path === "") return [];
  return path.split("/");
}

function navigate(root: any, tokens: string[]) {
  let current = root;
  for (const t of tokens) {
    const unescaped = t.replace(/~1/g, "/").replace(/~0/g, "~");
    if (current === null || typeof current !== 'object') return undefined;
    current = current[unescaped];
  }
  return current;
}

function matchesType(instance: any, type: any): boolean {
  const types = Array.isArray(type) ? type : [type];
  for (const t of types) {
    if (t === 'null') {
      if (instance === null) return true;
    } else if (s_type_check(t, instance)) {
      return true;
    }
  }
  return false;
}

function s_type_check(t: string, instance: any): boolean {
  if (t === 'boolean') return typeof instance === 'boolean';
  if (t === 'number') return typeof instance === 'number';
  if (t === 'integer') return typeof instance === 'number' && Number.isInteger(instance);
  if (t === 'string') return typeof instance === 'string';
  if (t === 'object') return instance !== null && typeof instance === 'object' && !Array.isArray(instance);
  if (t === 'array') return Array.isArray(instance);
  return false;
}

function deepEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return a === b;
  if (typeof a !== 'object') return a === b;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (Array.isArray(b)) return false;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) return false;
  }
  return true;
}

function validate(instance: any, schema: any, L: string[], P: string[], root: any, errors: ErrorPair[]) {
  if (schema === true) return;
  if (schema === false) {
    errors.push({ sL: formatPointer(L), sP: formatPointer(P), L: [...L], P: [...P] });
    return;
  }

  if (schema.hasOwnProperty('$ref')) {
    const refPath = parsePointer(schema.$ref);
    const refSchema = navigate(root, refPath);
    validate(instance, refSchema, L, refPath, root, errors);
    return;
  }

  if (schema.hasOwnProperty('type')) {
    if (!matchesType(instance, schema.type)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['type'])), L: [...L], P: P.concat(['type']) });
    }
  }

  if (schema.hasOwnProperty('enum')) {
    let found = false;
    for (const item of schema.enum) {
      if (deepEqual(instance, item)) {
        found = true;
        break;
      }
    }
    if (!found) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['enum'])), L: [...L], P: P.concat(['enum']) });
    }
  }

  if (schema.hasOwnProperty('const')) {
    if (!deepEqual(instance, schema.const)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['const'])), L: [...L], P: P.concat(['const']) });
    }
  }

  if (typeof instance === 'number') {
    if (schema.hasOwnProperty('minimum') && !(instance >= schema.minimum)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['minimum'])), L: [...L], P: P.concat(['minimum']) });
    }
    if (schema.hasOwnProperty('maximum') && !(instance <= schema.maximum)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['maximum'])), L: [...L], P: P.concat(['maximum']) });
    }
    if (schema.hasOwnProperty('exclusiveMinimum') && !(instance > schema.exclusiveMinimum)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['exclusiveMinimum'])), L: [...L], P: P.concat(['exclusiveMinimum']) });
    }
    if (schema.hasOwnProperty('exclusiveMaximum') && !(instance < schema.exclusiveMaximum)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['exclusiveMaximum'])), L: [...L], P: P.concat(['exclusiveMaximum']) });
    }
  }

  if (typeof instance === 'string') {
    if (schema.hasOwnProperty('minLength') && (instance.length < schema.minLength)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['minLength'])), L: [...L], P: P.concat(['minLength']) });
    }
    if (schema.hasOwnProperty('maxLength') && (instance.length > schema.maxLength)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['maxLength'])), L: [...L], P: P.concat(['maxLength']) });
    }
  }

  if (Array.isArray(instance)) {
    if (schema.hasOwnProperty('minItems') && (instance.length < schema.minItems)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['minItems'])), L: [...L], P: P.concat(['minItems']) });
    }
    if (schema.hasOwnProperty('maxItems') && (instance.length > schema.maxItems)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['maxItems'])), L: [...L], P: P.concat(['maxItems']) });
    }
    if (schema.hasOwnProperty('uniqueItems') && schema.uniqueItems === true) {
      let unique = true;
      for (let i = 0; i < instance.length; i++) {
        for (let j = i + 1; j < instance.length; j++) {
          if (deepEqual(instance[i], instance[j])) {
            unique = false;
            break;
          }
        }
        if (!unique) break;
      }
      if (!unique) {
        errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['uniqueItems'])), L: [...L], P: P.concat(['uniqueItems']) });
      }
    }
    if (schema.hasOwnProperty('prefixItems')) {
      const prefixItems = schema.prefixItems;
      for (let i = 0; i < prefixItems.length && i < instance.length; i++) {
        validate(instance[i], prefixItems[i], L.concat([i.toString()]), P.concat(['prefixItems', i.toString()]), root, errors);
      }
    }
    if (schema.hasOwnProperty('items')) {
      const items = schema.items;
      if (Array.isArray(items)) {
        for (let i = 0; i < items.length && i < instance.length; i++) {
          validate(instance[i], items[i], L.concat([i.toString()]), P.concat(['items', i.toString()]), root, errors);
        }
      } else {
        const start = (schema.prefixItems ? schema.prefixItems.length : 0);
        for (let i = start; i < instance.length; i++) {
          validate(instance[i], items, L.concat([i.toString()]), P.concat(['items']), root, errors);
        }
      }
    }
  }

  if (instance !== null && typeof instance === 'object' && !Array.isArray(instance)) {
    if (schema.hasOwnProperty('minProperties') && (Object.keys(instance).length < schema.minProperties)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['minProperties'])), L: [...L], P: P.concat(['minProperties']) });
    }
    if (schema.hasOwnProperty('maxProperties') && (Object.keys(instance).length > schema.maxProperties)) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['maxProperties'])), L: [...L], P: P.concat(['maxProperties']) });
    }
    if (schema.hasOwnProperty('required')) {
      for (let i = 0; i < schema.required.length; i++) {
        const name = schema.required[i];
        if (!(name in instance)) {
          errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['required', i.toString()])), L: [...L], P: P.concat(['required', i.toString()]) });
        }
      }
    }
    if (schema.hasOwnProperty('properties')) {
      for (const name in schema.properties) {
        if (name in instance) {
          validate(instance[name], schema.properties[name], L.concat([name]), P.concat(['properties', name]), root, errors);
        }
      }
    }
    if (schema.hasOwnProperty('additionalProperties')) {
      const properties = schema.properties || {};
      for (const name in instance) {
        if (!properties.hasOwnProperty(name)) {
          validate(instance[name], schema.additionalProperties, L.concat([name]), P.concat(['additionalProperties']), root, errors);
        }
      }
    }
  }

  if (schema.hasOwnProperty('allOf')) {
    for (let i = 0; i < schema.allOf.length; i++) {
      validate(instance, schema.allOf[i], L, P.concat(['allOf', i.toString()]), root, errors);
    }
  }
  if (schema.hasOwnProperty('anyOf')) {
    let anyOfAccepts = false;
    for (const sub of schema.anyOf) {
      const subErrors: ErrorPair[] = [];
      validate(instance, sub, L, P.concat(['anyOf']), root, subErrors);
      if (subErrors.length === 0) {
        anyOfAccepts = true;
        break;
      }
    }
    if (!anyOfAccepts) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['anyOf'])), L: [...L], P: P.concat(['anyOf']) });
    }
  }
  if (schema.hasOwnProperty('oneOf')) {
    let count = 0;
    for (const sub of schema.oneOf) {
      const subErrors: ErrorPair[] = [];
      validate(instance, sub, L, P.concat(['oneOf']), root, subErrors);
      if (subErrors.length === 0) {
        count++;
      }
    }
    if (count !== 1) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['oneOf'])), L: [...L], P: P.concat(['oneOf']) });
    }
  }
  if (schema.hasOwnProperty('not')) {
    const subErrors: ErrorPair[] = [];
    validate(instance, schema.not, L, P.concat(['not']), root, subErrors);
    if (subErrors.length === 0) {
      errors.push({ sL: formatPointer(L), sP: formatPointer(P.concat(['not'])), L: [...L], P: P.concat(['not']) });
    }
  }
  if (schema.hasOwnProperty('if')) {
    const ifErrors: ErrorPair[] = [];
    validate(instance, schema.if, L, P.concat(['if']), root, ifs = ifErrors);
    function ifs(e: ErrorPair[]) {} 
    if (ifErrors.length === 0) {
      if (schema.hasOwnProperty('then')) {
        validate(instance, schema.then, L, P.concat(['then']), root, errors);
      }
    } else {
      if (schema.hasOwnProperty('else')) {
        validate(instance, schema.else, L, P.concat(['else']), root, errors);
      }
    }
  }
}

function main() {
  const dir = process.argv[2];
  if (!dir) return;
  const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf8'));
  const instances = JSON.parse(fs.readFileSync(path.join(dir, 'instances.json'), 'utf8'));

  let validCount = 0;
  let invalidCount = 0;

  for (let i = 0; i < instances.length; i++) {
    const instance = instances[i];
    const errors: ErrorPair[] = [];
    validate(instance, schema, [], [], schema, errors);

    if (errors.length ===  === 0) {
      console.log(`${i}: valid`);
      validCount++;
    } else {
      const uniqueErrors = new Map<string, ErrorPair>();
      for (const err of errors) {
        const key = `${err.sL} ${err.sP}`;
        if (!uniqueErrors.has(key)) {
          uniqueErrors.set(key, err);
        }
      }
      const uniqueList: ErrorPair[] = Array.from(uniqueErrors.values());
      uniqueList.sort((a, b) => {
        if (a.sL !== b.sL) return a.sL < b.sL ? -1 : 1;
        if (a.sP !== b.sP) return a.sP < b.sP ? -1 : 1;
        return 0;
      });

      console.log(`${i}: invalid (${uniqueList.length})`);
      for (const err of uniqueList) {
        console.log(`  ${err.sL} ${err.sP}`);
      }
      invalidCount++;
    }
  }
  console.log(`valid=${validCount} invalid=${invalidCount}`);
}

main();

import sys
