def base64_decode_strict(s):
    """Decodes a base64url-encoded string with strict checks for unused bits and length."""
    if not s:
        return None
    if len(s) % 4 == 1:
        return None
    if not all(c in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_" for c in s):
        return None

    table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
    val_map = {c: i for i, c in enumerate(table)}

    bit_stream = 0
    bit_count = 0
    for char in s:
        bit_stream = (bit_stream << 6) | val_map[char]
        bit_count += 6

    byte_count = bit_count // 8
    unused_bits_count = bit_count % 8

    mask = (1 << unused_bits_count) - s.count('=') # The mask is for the remaining bits
    # However, the rule is "a length that is not 1 more than a multiple of 4" is malformed.
    # For the unused bits:
    mask = (1 << unused_bits_count) - 1
    if (bit_stream & mask) != 0:
        return None

    try:
        if byte_count == 0:
            return b''
        return (bit_stream >> unused_bits_count).to_bytes(byte_count, 'big')
    except:
        return None

def parse_json_no_duplicates(s):
    """Parses JSON and raises error if duplicate keys are found."""
    try:
        def dict_cb(pairs):
            d = {}
            for k, v in pairs:
                if k in d:
                    raise ValueError("Duplicate key")
                d[k] = v
            return d
        return json.loads(s, object_pairs_hook=dict_cb)
    except:
        return None

def solve():
    if len(sys.argv) < 2:
        return
    dir_path = sys.argv[1]
    config_path = os.path.join(dir_path, 'config.json')
    tokens_path = os.path.join(dir_path, 'tokens.txt')

