        with open(config_path, 'r') as f:
            config = json.load(f)
        with open(tokens_path, 'r') as f:
            lines = f.readlines()
    except:
        return

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = config['keys']

    valid_count = 0
    invalid_count = 0

    token_idx = 1
    for line in lines:
        line = line.strip()
        if not line:
            continue

        status = ""
        segments = line.split('.')

        if len(segments) != 3:
            status = "MALFORMED"
        else:
            b_segments = []
            possible_malformed = False
            for seg in segments:
                b = base64_decode_strict(seg)
                if b is None:
                    possible_malformed = True
                    break
                b_segments.append(b)

            if possible_malformed:
                status = "MALFORMED"
            else:
                try:
                    header_bytes = b_segments[0]
                    payload_bytes = b_segments[1]
                    sig_bytes = b_segments[2]

                    header_str = header_bytes.decode('utf-8')
                    payload_str = payload_bytes.decode('utf-8')

                    header_json = parse_json_no_duplicates(header_str)
                    payload_json = parse_json_no_duplicates(payload_str)

                    if header_json is None or not isinstance(header_json, dict) or \
                       payload_json is None or not isinstance(payload_json, dict):
                        status = "MALFORMED"
                    else:
                        alg = header_json.get('alg')
                        if not isinstance(alg, str) or alg not in ['HS256', 'HS384', 'HS512']:
                            status = "UNSUPPORTED_ALG"
