                                    else: # HS512
                                        expected_sig = hmac.new(k_secret, msg, hashlib.sha512).digest()

                                    if sig_bytes != expected_sig:
                                        status = "BAD_SIGNATURE"
                                    else:
                                        exp_val = payload_json.get('exp')
                                        nbf_val = payload_json.get('nbf')
                                        iss_val = payload_json.get('iss')
                                        aud_val = payload_json.get('aud')

                                        if exp_val is not None:
                                            if not isinstance(exp_val, (int, float)) or not (now < exp_val + leeway):
                                                status = "EXPIRED"

                                        if status == "" and nbf_val is not None:
                                            if not isinstance(nbf_val, (int, float)) or not (now + leeway < nbf_val):
                                                status = "NOT_YET_VALID"

                                        if status == "" and (not isinstance(iss_val, str) or issq_val := iss_val != issuer):
                                            # Note: The above line is a placeholder for the logic below
