                                                status = "BAD_ISSUER"

                                        if status == "":
                                            if isinstance(aud_val, str):
                                                if aud_val != audience:
                                                    status = "BAD_AUDIENCE"
                                            elif isinstance(aud_val, list):
                                                if audience not in aud_val:
                                                    status = "BAD_AUDIENCE"
                                            else:
                                                status = "BAD_AUDIENCE"

                                        if status == "":
                                            sub_val = payload_json.get('sub', '')
                                            scope_val = payload_json.get('scope', '')
                                            if isinstance(scope_val, str):
