def decode_key_final(s):
    """Decodes the base64url-encoded secret key."""
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
    char_to_val = {c: i for i, c in enumerate(alphabet)}
    val = 0
    for char in s:
        val = (val << 6) | char_to_val[char]
    total_bits = len(s) * 6
    byte_count = total_bits // 8
    return (val >> (total_bits % 8)).to_bytes(byte_count, 'big')

