fn parse_json_string(bytes: &[u8], pos: &mut usize) -> Option<String> {
    if *pos >= bytes.len() || bytes[*pos] != b'"' { return None; }
    *pos += 1;
    let mut res = String::new();
    while *pos < bytes.len() {
        if bytes[*pos] == b'\\' {
            *pos += 1;
            if *pos >= bytes.len() { return None; }
            match bytes[*pos] {
                b'"' => res.push('"'),
                b'\\' => res.push('\\'),
                b'/' => res.push('/'),
                b'b' => res.push('\x08'),
                b'f' => res.push('\x0c'),
                b'n' => res.push('\n'),
                b'r' => res.push('\r'),
                b't' => res.push('\t'),
                b'u' => {
                    let mut hex = String::new();
                    for _ in 0..4 {
                        *pos += 1;
                        if *pos >= bytes.len() { return None; }
                        hex.push(bytes[*pos] as char);
                    }
                    let code = u32::from_str_radix(&hex, 16).ok()?;
                    let c = std::char::from_u32(code)?;
                    res.push(c);
                }
                _ => return None,
            }
        } else if bytes[*pos] == b'"' {
            *pos += 1;
            return Some(res);
        } else {
            res.push(bytes[*pos] as char);
            *pos += 1;
        }
    }
    None
}

fn parse_json_number(bytes: &[u8], pos: &mut usize) -> Option<JsonValue> {
    let start = *pos;
    if *pos < bytes.len() && bytes[*pos] == b'-' { *pos += 1; }
    if *pos < bytes.len() && bytes[*pos] == b'0' {
        *pos += 1;
    } else {
        while *pos < bytes.len() && bytes[*pos].is_ascii_digit() { *pos += 1; }
        if *pos < bytes.len() && bytes[*pos] == b'.' {
            *pos += 1;
            while *pos < bytes.len() && bytes[*pos].is_ascii_digit() { *pos += 1; }
        }
        if *pos < bytes.len() && (bytes[*pos] == b'e' || bytes[*pos] == b'E') {
            *pos += 1;
            if *pos < bytes.len() && (bytes[*pos] == b'+' || bytes[*pos] == b'-') { *pos += 1; }
            while *pos < bytes.len() && bytes[*pos].is_ascii_digit() { *pos += 1; }
        }
    }
    let s = std::str::from_utf8(&bytes[start..*pos]).ok()?;
    let val = s.parse::<f64>().ok()?;
    Some(JsonValue::Number(val))
}

fn b64_decode(input: &str) -> Option<Vec<u8>> {
    let bytes = input.as_bytes();
    if input.len() % 4 == 1 { return None; }
    let mut res = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0;
    for &b in bytes {
        let v = match b {
            b'A'..=b'Z' => b - b'A',
            b'a'..=b'z' => b - b'a' + 26,
            b'0'..=b'9' => b - b'0' + 52,
            b'-' => 62,
            b'_' => 63,
            _ => return None,
        };
        buffer = (buffer << 6) | (v as u32);
        bits += 6;
        if bits >= 8 {
            res.push((buffer >> (bits - 8)) as u8);
            bits -= 8;
        }
    }
    if bits > 0 && (buffer & ((1 << bits) - 1)) != 0 { return None; }
    Some(res)
}

fn sha256(data: &[u8]) -> [u8; 32] {
    let mut hasher = Sha2::new(false);
    hasher.update(data);
    hasher.finalize_256()
}

fn sha512(data: &[u8]) -> [u8; 64] {
    let mut hasher = Sha2::new(true);
    hasher.update(data);
    hasher.finalize_512()
}

struct Sha2 {
    is_512: bool,
    state: [u64; 8],
    buffer: Vec<u8>,
}

impl Sha2 {
    fn new(is_512: bool) -> Self {
        let state = if is_512 {
            [0x6a09e667f3bcc908, 0xbb67ae85ec2f8cd4, 0x3c6ef372aefc17fa, 0xa54ff53a5f1d36f1, 0x510e527fade682d1, 0x9b05688c2b3e6c1f, 0x1f83d9abbaad02d2, 0x5be0cd19e372fcfa]
        } else {
            [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
        };
        Self { is_512, state, buffer: Vec::new() }
    }

    fn update(&mut self, data: &[u8]) {
        self.buffer.extend_from_slice(data);
        let block_size = if self.is_512 { 128 } else { 64 };
        while self.buffer.len() >= block_size {
            let block = self.buffer.drain(0..block_size).collect::<Vec<_>>();
            self.process_block(&block);
        }
