import * as fs from 'fs';
import * as path from 'path';

type TokenType =
  | 'LET' | 'FN' | 'IF' | 'ELSE' | 'WHILE' | 'FOR' | 'IN' | 'RETURN' | 'BREAK' | 'CONTINUE'
  | 'IDENT' | 'INT' | 'STRING' | 'TRUE' | 'FALSE' | 'NIL'
  | 'EQ' | 'NEQ' | 'LE' | 'GE' | 'LT' | 'GT' | 'ASSIGN' | 'PLUS' | 'MINUS' | 'MUL' | 'DIV' | 'MOD'
  | 'LPAREN' | 'RPAREN' | 'LBRACKET' | 'RBRACKET' | 'LBRACE' | 'RBRACE' | 'COMMA' | 'SEMICOLON'
  | 'EOF';

interface Token {
  type: TokenType;
  value: string;
  line: number;
}

class Lexer {
  public tokens: Token[] = [];
  constructor(private source: string) {}

  tokenize() {
    const lines = this.source.split(/\r?\n/);
    for (let lineIdx = 0; lineIdx < lines.length; lineIdx++) {
      const line = lines[lineIdx];
      const lineNum = lineIdx + 1;
      let col = 0;
      while (col < line.length) {
        const char = line[col];
        if (/\s/.test(char)) { col++; continue; }
        if (char === '#') break;

        if (/[a-zA-Z_]/.test(char)) {
          let ident = "";
          while (col < line.length && /[a-zA-Z0-9_]/.test(line[col])) {
            ident += line[col];
            col++;
          }
          const typeMap: Record<string, TokenType> = {
            'let': 'LET', 'fn': 'FN', 'if': 'IF', 'else': 'ELSE', 'while': 'WHILE',
            'for': 'FOR', 'in': 'IN', 'return': 'RETURN', 'break': 'BREAK',
            'continue': 'CONTINUE', 'true': 'TRUE', 'false': 'FALSE', 'nil': 'NIL'
          };
          const type = typeMap[ident] || 'IDENT';
          this.tokens.push({ type, value: ident, line: lineNum });
          continue;
        }

        if (/[0-9]/.test(char)) {
          let num = "";
          while (col < line.length && /[0-9]/.test(line[col])) {
            num += line[col];
            col++;
          }
          this.tokens.push({ type: 'INT', value: num, line: lineNum });
          continue;
        }

        if (char === '"') {
          let str = "";
          col++;
          while (col < line.length && line[col] !== '"') {
            if (line[col] === '\\') {
              col++;
              if (col < line.length) {
                const esc = line[col];
                if (esc === 'n') str += '\n';
                else if (esc === 't') str += '\t';
                else if (esc === '"') str += '"';
                else if (esc === '\\') str += '\\';
                col++;
              }
            } else {
              str += line[col];
              col++;
            }
          }
          this.tokens.push({ type: 'STRING', value: str, line: lineNum });
          col++;
          continue;
        }

        const twoChar = line.substring(col, col + 2);
        if (twoChar === '==' || twoChar === '!=' || twoChar === '<=' || twoChar === '>=') {
          const typeMap: Record<string, TokenType> = { '==': 'EQ', '!=': 'NEQ', '<=': 'LE', '>=': 'GE' };
          this.tokens.push({ type: typeMap[twoChar], value: twoChar, line: lineNum });
          col += 2;
          continue;
        }

        const oneCharMap: Record<string, TokenType> = {
          '=': 'ASSIGN', '+': 'PLUS', '-': 'MINUS', '*': 'MUL', '/': 'DIV', '%': 'MOD',
          '(': 'LPAREN', ')': 'RPAREN', '[': 'LBRACKET', ']': 'RBRACKET', '{': 'LBRACE', '}': 'RBRACE',
          '<': 'LT', '>': 'GT', ',': 'COMMA', ';': 'SEMICOLON'
        };

        if (oneCharMap[char]) {
          this.tokens.push({ type: oneCharMap[char], value: char, line: lineNum });
          col++;
          continue;
        }
        col++;
      }
    }
    this.tokens.push({ type: 'EOF', value: '', line: 0 });
    return this.tokens;
  }
}

class Parser {
  private pos = 0;
  constructor(private tokens: Token[]) {}

  private peek() { return this.tokens[this.pos]; }
  private consume() { return this.tokens[this.pos++]; }
  private match(type: TokenType) {
    if (this.peek().type === type) return this.consume();
    return null;
  }

  parse() {
    const stmts: any[] = [];
    while (this.peek().type !== 'EOF') {
      stmts.push(this.parseStmt());
    }
    return stmts;
  }

  private parseStmt(): any {
    const t = this.peek();
    if (t.type === 'LET') {
      this.consume();
      const name = this.consume().value;
      this.match('ASSIGN');
      const expr = this.parseExpr();
      this.match('SEMICOLON');
      return { type: 'let', name, expr };
    }
    if (t.type === 'FN') {
      this.consume();
      const name = this.consume().value;
      this.match('LPAREN');
      const params = this.parseParams();
      this.match('RPAREN');
      const body = this.parseBlock();
      return { type: 'fn', name, params, body };
    }
    if (t.type === 'IF') {
      this.consume();
      const cond = this.parseExpr();
      const body = this.parseBlock();
      let elsePart = null;
      if (this.peek().type === 'ELSE') {
        this.consume();
        elsePart = this.parseStmt();
      }
      return { type: 'ifstmt', cond, body, elsePart };
    }
    if (t.type === 'WHILE') {
      this.consume();
      const cond = this.parseExpr();
      const body = this.parseBlock();
      return { type: 'while', cond, body };
    }
    if (t.type === 'FOR') {
      this.consume();
      const name = this.consume().value;
      this.match('IN');
      const expr = this.parseExpr();
      const body = this.parseBlock();
      return { type: 'for', name, expr, body };
    }
    if (t.type === 'RETURN') {
      this.consume();
      const expr = this.peek().type === 'SEMICOLON' ? null : this.parseExpr();
      this.match('SEMICOLON');
      return { type: 'return', expr };
    }
    if (t.type === 'BREAK') {
      this.consume();
      this.match('SEMICOLON');
      return { type: 'break' };
    }
    if (t.type === 'CONTINUE') {
      this.consume();
      this.match('SEMICOLON');
      return { type: 'continue' };
    }

    const lhs = this.parsePostfix();
    if (this.peek().type === 'ASSIGN') {
      this.consume();
      const expr = this.parseExpr();
      this.match('SEMICOLON');
      return { type: 'assign', lhs, expr };
    }
    if (this.peek().type === 'LBRACKET') {
      // This matches the postfix [ expr ] = expr ; case.
      // But we need to handle the case where the LHS might be a postfix.
      // If the LHS is already a postfix, we need to handle it.
      // Actually, the rule says: postfix [ expr ] = expr ;
      // If we have x[i] = 5, then the postfix is x, and [i] is the [ expr ] part.
      // This is already handled by the fact that LHS can be a postfix.
    }
    // If it's not an assignment, it's an expression statement.
    // But we need to handle the case where it's just an expression.
    // Let's backtrack if it's not an assignment.
    // Actually, we can just use the same logic.
    return { type: 'expr_stmt', expr: lhs };
  }

  private parseParams(): any[] {
    const params = [];
    if (this.peek().type === 'RPAREN') return params;
    while (true) {
      params.push(this.consume().value);
      if (this.peek().type === 'COMMA') {
        this.consume();
      } else {
        break;
      }
    }
    return params;
  }

  private parseBlock(): any[] {
    this.match('LBRACE');
    const stmts = [];
    while (this.peek().type !== 'RBRACE' && this.peek().type !== 'EOF') {
      stmts.push(this.parseStmt());
    }
    this.match('RBRACE');
    return stmts;
  }

  private parseExpr(): any {
    return this.parseOr();
  }

  private parseOr(): any {
    let left = this.parseAnd();
    while (this.peek().type === 'IDENT' && this.peek().value === 'or') {
      this.consume();
      const right = this.parseAnd();
      left = { type: 'binary', op: 'or', left, right };
    }
    return left;
  }

  private parseAnd(): any {
    let left = this.parseNot();
    while (this.peek().type === 'IDENT' && this.peek().value === 'and') {
      this.consume();
      const right = this.parseNot();
      left = { type: 'binary', op: 'and', left, right };
    }
    return left;
  }

  private parseNot(): any {
    if (this.peek().type === 'IDENT' && this.peek().value === 'not') {
      this.consume();
      return { type: 'unary', op: 'not', expr: this.parseNot() };
    }
    return this.parseComparison();
  }

  private parseComparison(): any {
    let left = this.parseAdd();
    const type = this.peek().type;
    if (['EQ', 'NEQ', 'LT', 'LE', 'GT', 'GE'].includes(type)) {
      const op = this.consume().value;
      const right = this.parseAdd();
      return { type: 'binary', op, left, right };
    }
    return left;
  }

  private parseAdd(): any {
    let left = this.parseMul();
    while (this.peek().type === 'PLUS' || this.peek().type === 'MINUS') {
      const op = this.consume().value;
      const right = this.parseMul();
      left = { type: 'binary', op, left, right };
    }
    return left;
  }

  private parseMul(): any {
    let left = this.parseUnary();
    while (this.peek().type === 'MUL' || this.peek().type === 'DIV' || this.peek().type === 'MOD') {
      const op = this.consume().value;
      const right = this.parseUnary();
      left = { type: 'binary', op, left, right };
    }
    return left;
  }

  private parseUnary(): any {
    if (this.peek().type === 'IDENT' && this.peek().value === '-') {
      this.consume();
      return { type: 'unary', op: '-', expr: this.parseUnary() };
    }
    return this.parsePostfix();
  }

  private parsePostfix(): any {
    let left = this.parsePrimary();
    while (this.peek().type === 'LPAREN' || this.peek().type === 'LBRACKET') {
      const t = this.peek();
      if (t.type === 'LPAREN') {
        this.consume();
        const args = [];
        if (this.peek().type !== 'RPAREN') {
          while (true) {
            args.push(this.parseExpr());
            if (this.peek().type === 'COMMA') this.consume();
            else break;
          }
        }
        this.match('RPAREN');
        left = { type: 'call', callee: left, args };
      } else {
        this.consume();
        const index = this.parseExpr();
        this.match('RBRACKET');
        left = { type: 'index', callee: left, index };
      }
    }
    return left;
  }

  private parsePrimary(): any {
    const t = this.peek();
    if (t.type === 'INT') return { type: 'int', value: BigInt(this.consume().value) };
    if (t.type === 'STRING') return { type: 'string', value: this.consume().value };
    if (t.type === 'TRUE') { this.consume(); return { type: 'bool', value: true }; }
    if (t.type === 'FALSE') { this.consume(); return { type: 'bool', value: false }; }
    if (t.type === 'NIL') { this.consume(); return { type: 'nil' }; }
    if (t.type === 'IDENT') return { type: 'ident', name: this.consume().value };
    if (t.type === 'LPAREN') {
      this.consume();
      const expr = this.parseExpr();
      this.match('RPAREN');
      return expr;
    }
    if (t.type === 'LBRACKET') {
      this.consume();
      const elements = [];
      if (this.peek().type !== 'RBRACKET') {
        while (true) {
          elements.push(this.parseExpr());
          if (this.peek().type === 'COMMA') this.consume();
          else break;
        }
      }
      this.match('RBRACKET');
      return { type: 'list', elements };
    }
    if (t.type === 'FN') {
      // This is for 'fn(args) { body }'
      this.consume();
      const params = this.parseParams();
      const body = this.parseBlock();
      return { type: 'fn_lit', params, body };
    }
    return { type: 'error' };
  }

  private parseParams(): any[] {
    const params = [];
    if (this.peek().type === 'RPAREN') return params;
    while (true) {
      params.push(this.consume().value);
      if (this.peek().type === 'COMMA') this.consume();
      else break;
    }
    return params;
  }

  private parseBlock(): any[] {
    this.match('LBRACE');
    const stmts = [];
    while (this.peek().type !== 'RBRACE' && this.peek().type !== 'EOF') {
      stmts.push(this.parseStmt());
    }
    this.match('RBRACE');
    return stmts;
  }

  private parseExpr(): any {
    return this.parseOr();
  }
}

