class Environment {
  constructor(public parent: Environment | null = null) {
    this.vars = new Map();
  }
  public vars = new Map<string, any>();
  get(name: string) {
    if (this.vars.has(name)) return this.vars.get(name);
    if (this.parent) return this.parent.get(name);
    return null;
  }
  set(name: string, value: any) {
    this.vars.set(name, value);
  }
  has(name: string) {
    if (this.vars.has(name)) return true;
    if (thiss_parent_has(this.parent, name)) return true;
    return false;
  }
}

function thiss_parent_has(env: Environment | null, name: string) {
  if (!env) return false;
  if (env.vars.has(name)) return true;
  return thiss_parent_has(env.parent, name);
}

class Interpreter {
  private env: Environment;
  private error: string | null = null;
  private errorLine: number = 0;

  constructor(private stmts: any[]) {
    this.env = new Environment();
  }

  run() {
    try {

      for (const stmt of this.stmts) {
        this.execute(stmt, this.env);
      }
    } catch (e: any) {
      if (e.message.startsWith('error at line')) {
        console.log(e.message);
      } else {
        console.log(e.message);
      }
    }
  }

  private execute(stmt: any, env: Environment): any {
    if (stmt.type === 'let') {
      const val = this.evaluate(stmt.expr, env);
      env.set(stmt.name, val);
      return;
    }
    if (stmt.type === 'fn') {
      const fn = { type: 'fn', params: stmt.params, body: stmt.body, env: env };
      env.set(stmt.name, fn);
      return;
    }
    if (stmt.type === 'ifstmt') {
      if (this.isTruthy(this.evaluate(stmt.cond, env))) {
        this.executeBody(stmt.body, env);
      } else if (stmt.elsePart) {
        this.executeBody(stmt.elsePart, env);
      }
      return;
    }
    if (stmt.type === 'while') {
      while (this.isTruthy(this.evaluate(stmt.cond, env))) {
        this.executeBody(stmt.body, env);
      }
      return;
    }
    if (stmt.type === 'for') {
      const list = this.evaluate(stmt.expr, env);
      if (!Array.isArray(list)) this.error(`cannot iterate ${this.typeOf(list)}`, 0);
      for (let i = 0; i < list.length; i++) {
        const iterEnv = new Environment(env);
        iterEnv.set(stmt.name, list[i]);
        this.executeBody(stmt.body, iterEnv);
      }
      return;
    }
    if (stmt.type === 'return') {
      const val = stmt.expr ? this.evaluate(stmt.expr, env) : null;
      throw { message: `return_val: ${val}` };
    }
    if (stmt.type === 'break') throw { message: 'break' };
    if (stmt.type === 'continue') throw { message: 'continue' };
    if (stmt.type === 'assign') {
      const val = this.evaluate(stmt.expr, env);
      this.assign(stmt.lhs, val, env);
      return;
    }
    if (stmt.type === 'expr_stmt') {
      return this.evaluate(stmt.expr, env);
    }
    if (stmt.type === === 'fn_lit') {
      const fn = { type: 'fn', params: stmt.params, body: stmt.body, env: env };
      env.set(stmt.name, fn);
      return;
    }
  }

  private executeBody(body: any[], env: Environment) {
    const newEnv = new Environment(env);
    for (const stmt of body) {
      try {
        this.execute(stmt, newEnv);
      } catch (e: any) {
        if (e.message === 'break') return;
        if (e.message === 'continue') {
          // This is tricky. We need to jump to the next iteration.
