        let c = self.peek();
        if c.is_some() { self.pos += 1; }
        c
    }
    fn consume_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c.is_whitespace() {
                if c == '\n' { self.line += 1; }
                self.advance();
            } else if c == '#' {
                while let Some(c) = self.peek() {
                    if c == '\n' { self.line += 1; self.advance(); break; }
                    self.advance();
                }
            } else { break; }
        }
    }
    fn next_token(&mut self) -> (Token, usize) {
        self.consume_whitespace();
        let line = self.line;
        let c = match self.peek() {
            Some(c) => c,
            None => return (Token::EOF, line),
        };
        if c.is_alphabetic() || c == '_' {
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c.is_alphanumeric() || c == '_' { s.push(self.advance().unwrap()); }
                else { break; }
            }
            let token = match s.as_str() {
                "let" => Token::Let, "fn" => Tokens::Fn, "if" => Token::If, "else" => Token::Else,
                "while" => Token::While, "for" => Token::For, "in" => Token::In, "return" => Token::Return,
                "break" => Token::Break, "continue" => Token::Continue, "true" => Token::True,
                "false" => Token::False, "nil" => Token::Nil, _ => Token::Identifier(s),
            };
            return (token, line);
        }
        if c.is_digit(10) {
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c.is_digit(10) { s.push(self.advance().unwrap()); }
                else { break; }
            }
            return (Token::Int(s.parse().unwrap()), line);
        }
        if c == '"' {
            self.advance();
            let mut s = String::new();
            while let Some(c) = self.peek() {
                if c == '"' { self.advance(); return (Token::String(s), line); }
                else if c == '\\' {
                    self.advance();
                    if let Some(nc) = self.advance() {
                        match nc { 'n' => s.push('\n'), 't' => s.push('\t'), '"' => s.push('"'), '\\' => s.push('\\'), _ => s.push(nc), }
                    }
                } else { s.push(self.advance().unwrap()); }
            }
        }
        self.advance();
        match c {
            '(' => Token::LParen, ')' => Token::RParen, '[' => Token::LBracket, ']' => Token::RBracket,
            '{' => Token::LBrace, '}' => Token::RBrace, ',' => Token::Comma, ';' => Token::Semicolon,
