}

func main() {
    let args = CommandLine.arguments
    if args.count < 2 { return }
    let sceneDir = args[1]
    let scenePath = (sceneDir as NSString).appendingPathComponent("scene.json")

    // Load and decode the scene from the JSON file.
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: scenePath)),
          let scene = try? JSONDecoder().decode(Scene.self, from: data) else {
        return
    }

    let width = scene.width
    let height = scene.height
    var canvas = [UInt8](repeating: 0, count: width * height * 3)

    // Initialize the canvas with the background color.
    for i in 0..<width * height {
        canvas[i * 3 + 0] = UInt8(scene.background[0])
        canvas[i * 3 + 1] = UInt8(scene.background[1])
        canvas[i * 3 + 2] = UInt8(scene.background[2])
    }

    // Process each shape in the order they appear in the JSON.
    for (index, shape) in scene.shapes.enumerated() {
        var coveredCount = 0
        let sR = Int64(shape.color[0])
        let sG = Int64(shape.color[1])
        let sB = Int64(shape.color[2])
        let A = shape.color.count == 4 ? Int64(shape.color[3]) : Int64(255)

        for y in 0..<height {
            for x in 0..<width {
                var isCovered = false

                switch shape.type {
                case .rect:
                    let rx = Int64(shape.x!)
                    let ry = Int64(shape.y!)
                    let w = Int64(shape.w!)
                    let h = Int64(shape.h!)
                    let px = Int64(x)
                    let py = Int64(y)
                    if px >= rx && px < rx + w && py >= ry && py < ry + h {
                        isCovered = true
                    }
                case .circle:
                    let cx = Int64(shape.cx!)
                    let cy = Int64(shape.cy!)
                    let r = Int64(shape.r!)
                    let px = Int64(x)
                    let py = Int64(y)
                    let dx = px - cx
                    let dy = py - cy
                    if dx * dx + dy * dy <= r * r {
                        isCovered = true
                    }
                case .triangle:
                    let p0 = shape.points![0]
                    let p1 = shape.points![1]
                    let p2 = shape.points![2]
                    let x0 = Int64(p0[0]), y0 = Int64(p0[1])
                    let x1 = Int64(p1[0]), y1 = Int64(p1[1])
                    let x2 = Int64(p2[0]), y2 = Int64(p2[1])
                    let px = Int64(x), py = Int64(y)

                    let e0 = (x1 - x0) * (py - y0) - (y1 - y0) * (px - x0)
                    let e1 = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
                    let e2 = (x0 - x2) * (py - y2) - (y0 - y2) * (px - x2)

                    if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                        isCovered = true
                    }
                case .line:
                    let x1 = Int64(shape.x1!)
                    let y1 = = Int64(shape.y1!)
                    let x2 = Int64(shape.x2!)
                    let y2 = Int64(shape.y2!)
                    let r = Int64(shape.r!)
                    let px = Int64(x)
                    let py = Int64(y)

                    let dx = x2 - x1
                    let dy = y2 - y1
                    let L = dx * dx + dy * dy
                    let t = (px - x1) * dx + (py - y1) * dy

                    if L == 0 {
                        if (px - x1) * (px - x1) + (py - y1) * (py - y1) <= r * r {
                            isCovered = true
                        }
                    } else {
                        if t <= 0 {
                            if (px - x1) * (px - x1) + (py - y1) * (py - y1) <= r * r {
                                isCovered = true
                            }
                        } else if t >= L {
                            if (px - x2) * (px - x2) + (py - y2) * (py - y2) <= r * r {
                                isCovered = true
                            }
                        } else {
                            let c = (px - x1) * dy - (py - y1) * dx
                            if c * c <= r * r * L {
                                isCovered = true
                            }
                        }
                    }
                }

                if isCovered {
                    coveredCount += 1
                    let idx = (y * width + x) * 3
                    let dR = Int64(canvas[idx + 0])
                    let dG = Int64(canvas[idx + 1])
                    let dB = Int64(canvas[idx + 2])

