                    let newG = (sG * A + dG * (255 - A) + 127) / 255
                    let newB = (sB * A + dB * (255 - A) + 127) / 255

                    canvas[idx + 0] = UInt8(newR)
                    canvas[idx + 1] = UInt8(newG)
                    canvas[idx + 2] = UInt8(newB)
                }
            }
        }
        print("\(index + 1) \(shape.type.rawValue) \(coveredCount)")
    }

    // Count distinct colors in the final canvas.
    var colorSet = Set<RGB>()
    for y in 0..<height {
        for x in 0..<width {
            let idx = (y * width + x) * 3
            colorSet.insert(RGB(r: canvas[idx + 0], g: canvas[idx + 1], b: canvas[idx + 2]))
        }
    }
    print("colors \(colorSet.count)")

    // Generate the final PNG image from the canvas.
    let colorSpace = CGColorSpaceCreateDeviceRGB()
    let bitmapInfo = CGImageAlphaInfo.none.rawValue
    let context = CGContext(data: UnsafeMutableRawPointer(mutating: canvas), width: width, height: height, bitsPerComponent: 8, bytesPerRow: width * 3, space: colorSpace, bitmapInfo: bitmapInfo)

