// Define structures to represent the scene and its shapes as described in the JSON.
struct Scene: Decodable {
    let width: Int
    let height: Int
    let background: [Int]
    let shapes: [Shape]
}

struct Shape: Decodable {
    let type: String
    let x: Int?
    let y: Int?
    let w: Int?
    let h: Int?
    let cx: Int?
    let cy: Int?
    let r: Int?
    let points: [[Int]]?
    let x1: Int?
    let y1: Int?
    let x2: Int?
    let y2: Int?
    let color: [Int]
}

// A simple RGB structure to facilitate counting distinct colors in the final image.
struct RGB: Hashable {
    let r, g, b: UInt8
}

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { return }
    let sceneDir = args[1]
    let sceneURL = URL(fileURLWithPath: sceneDir).appendingPathComponent("scene.json")

    // Load and decode the scene from the JSON file.
    guard let data = try? Data(contentsOf: sceneURL),
          let scene = try? JSONDecoder().decode(Scene.self, from: data) else {
        return
    }

    let width = scene.width
    let height = scene.height
    var canvas = [UInt8](repeating: 0, count: width * height * 3)

    // Initialize the canvas with the background color.
    for i in 0..<width * height {
        canvas[i * 3 + 0] = UInt8(scene.background[0])
        canvas[i * 3 + 1] = UInt8(scene.background[1])
        canvas[i * 3 + 2] = UInt8(scene.background[2])
    }

    // Process each shape in the order they appear in the JSON.
    for (index, shape) in scene.shapes.enumerated() {
        var coveredCount = 0
        let sR = Int64(shape.color[0])
        let sG = Int64(shape.color[1])
        let sB =도 Int64(shape.color[2])
        let A = shape.color.count >= 4 ? Int64(shape.color[3]) : Int64(255)

        for y in 0..<height {
            for x in 0..<width {
                var isCovered = false
                let px = Int64(x)
                let py = Int64(y)

                if shape.type == "rect" {
                    let rx = Int64(shape.x!)
                    let ry =도 Int64(shape.y!)
                    let w = Int64(shape.w!)
                    let h = Int64(shape.h!)
                    if px >= rx && px < rx + w && py >= ry && py < ry + h {
                        isCovered = true
                    }
                } else if shape.type == "circle" {
                    let cx = Int64(shape.cx!)
                    let cy = Int64(shape.cy!)
                    let r = Int64(shape.r!)
                    let dx = px - cx
                    let dy = py - cy
                    if dx * dx + dy * dy <= r * r {
                        isCovered = true
                    }
                } else if shape.type == "triangle" {
                    let p0 = shape.points![0]
                    let p1 = shape.points![1]
                    let p2 = shape.points![2]
                    let x0 = Int64(p0[0]), y0 = Int64(p0[1])
                    let x1 = Int64(p1[0]), y1 = Int64(p1[1])
                    let x2 = Int64(p2[0]), y2 = Int64(p2[1])

                    let e0 = (x1 - x0) * (py - y0) - (y1 - y0) * (px - x0)
                    let e1 = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
                    let e2 = (x0 - x2) * (py - y2) - (y0 - y2) * (px - x2)

                    if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                        isCovered = true
                    }
                } else if shape.type == "line" {
                    let x1_val = Int64(shape.x1!)
                    let y1_val = Int64(shape.y1!)
                    let x2_val = Int64(shape.x2!)
                    let y2_val = Int64(shape.y2!)
                    let r_val = Int64(shape.r!)

                    let dx = x2_val - x1_val
                    let dy = y2_val - y1_val
                    let L = dx * dx + dy * dy
                    let t = (px - x1_val) * dx + (py - y1_val) * dy

                    if L == 0 {
                        if (px - x1_val) * (px - x1_val) + (py - y1_val) * (py - y1_val) <= r_val * r_val {
                            isCovered = true
                        }
                    } else {
                        if t <= 0 {
                            if (px - x1_val) * (px - x1_val) + (py - y1_val) * (py - y1_val) <= r_val * r_val {
                                isCovered = true
                            }
                        } else if t >= L {
                            if (px - x2_val) * (px - x2_val) + (py - y2_val) * (py - y2_val) <= r_val * r_val {
                                isCovered = true
                            }
                        } else {
                            let c = (px - x1_val) * dy - (py - y1_val) * dx
                            if c * c <= r_val * r_val * L {
                                isCovered = true
                            }
                        }
                    }
                }

                if isCovered {
                    coveredCount += 1
                    let idx = (y * width + x) * 3
                    let dR = Int64(canvas[idx + 0])
                    let dG = Int64(canvas[idx + 1])
                    let dB = Int64(canvas[idx + 2])

                    canvas[idx + 0] = UInt8((sR * A + dR * (255 - A) + 127) / 255)
                    canvas[idx + 1] = UInt8((sG * A + dG * (255 - A) + 127) / 255)
                    canvas[idx + 2] = UInt8((sB * A + dB * (255 - A) + 127) / 255)
                }
            }
        }
        print("\(index + 1) \(shape.type) \(coveredCount)")
    }

    // Count distinct colors in the final canvas.
    var colorSet = Set<RGB>()
    for y in 0..<height {
        for x in 0..<width {
            let idx = (y * width + x) * 3
            colorSet.insert(RGB(r: canvas[idx + 0], g:
                                canvas[idx + 1], b: canvas[idx + 2]))
        }
    }
    print("colors \(colorSet.count)")

    // Generate the final PNG image from the canvas.
    let colorSpace = CGColorSpaceCreateDeviceRGB()

    // Use withUnsafeMutableBytes to ensure the buffer is valid during the entire context lifecycle.
    canvas.withUnsafeMutableBytes { bytes in
        let context = CGContext(data: bytes.baseAddress,
                                width: width,
                                height: height,
                                bitsPerComponent: 8,
                                bytesPerRow: width * 3,
                                space: colorSpace,
                                bitmapInfo: CGImageAlphaInfo.none.rawValue)

        if let cgImage = context?.makeImage() {
            let outURL = URL(fileURLWithPath: "out.png")
            if let destination = CGImageDestinationCreateWithURL(outURL as CFURL, "public.png" as CFString, 1, nil) {
                CGImageDestinationAddImage(destination, cgImage, nil)
                CGImageDestinationFinalize(destination)
            }
        }
    }
}

