// Adler-32 implementation
struct Adler32 {
    static func compute(data: [UInt8]) -> UInt32 {
        var s1: UInt32 = 1
        var s2: UInt32 = 0
        for byte in data {
            s1 = (s1 + UInt32(byte)) % 65521
            s2 = (s2 + s1) % 65521
        }
        return (s2 << 16) | s1
    }
}

class BitReader {
    let data: [UInt8]
    var bitOffset: Int = 0

    init(data: [UInt8]) {
        self.data = data
    }

    func readBit() -> Int {
        let byteIdx = bitOffset / 8
        if byteIdx >= data.count { return     0 }
        let bitIdx = 7 - (bitOffset % 8)
        let bit = Int((data[byteIdx] >> bitIdx) & 1)
        bitOffset += 1
        return bit
    }

    func readBits(_ n: Int) -> Int {
        var res = 0
        for _ in 0..<n {
            res = (res << 1) | readBit()
        }
        return res
    }

    func hasBits(_ n: Int) -> Bool {
        return bitOffset + n <= data.count * 8
    }
}

