        canvas[y][x] = (newR << 16) | (newG << 8) | newB;
    }

    // The above updateCanvas has a small error in the variable names. Let's fix it.
    private static void updateCanvasFixed(int[][] canvas, int x, int y, int[] color) {
        int sR = color[0], sG = color[1], sB = color[2], A = color[3];
        int dR = (canvas[y][x] >> 16) & 0xFF;
        int dG = (canvas[y][x] >> 8) & 0xFF;
        int dB = canvas[y][x] & 0xFF;
        int newR = (sR * A + dR * (255 - A) + 127) / 255;
        int newG = (sG * A + dG * (255 - A) + 127) / 255;
        int newB = (sB * A + dB * (255 - A) + 127) / 255;
        canvas[y][x] = (newR << 16) | (newG << 8) | newB;
    }
}

