function solve() {
    const args = process.argv.slice(2);
    if (args.length === 0) return;
    const dir = args[0];
    const scenePath = path.join(dir, 'scene.json');
    const scene = JSON.parse(fs.readFileSync(scenePath, 'utf8'));

    const width = scene.width;
    const height = scene.height;
    const background = scene.background;
    const shapes = scene.shapes;

    const canvas = new Uint8Array(width * height * 3);
    for (let i = 0; i < width * height; i++) {
        canvas[i * 3] = background[0];
        canvas[i * 3 + 1] = background[1];
        canvas[i * 3 + 2] = background[2];
    }

    const results: string[] = [];

    for (let i = 0; i < shapes.length; i++) {
        const shape = shapes[i];
        const type = shape.type;
        let count = 0;

        const sR = shape.color[0];
        const sG = shape.color[1];
        const sB = shape.color[2];
        const A = shape.color[3];

        const blend = (idx: number, s: number, d: number) => {
            return Math.floor((s * A + d * (255 - A) + 127) / 255);
        };

        if (type === 'rect') {
            const { x, y, w, h } = shape;
            for (let py = 0; py < height; py++) {
                for (let px = 0; px < width; px++) {
                    if (px >= x && px < x + w && py >= y && py < y + h) {
                        count++;
                        const idx = (py * width + px) * 3;
                        canvas[idx] = blend(idx, sR, canvas[idx]);
                        canvas[idx + 1] = blend(idx + 1, sG, canvas[idx + 1]);
                        canvas[idx + 2] = blend(idx + 2, sB, canvas[idx + 2]);
                    }
                }
            }
        } else if (type === 'circle') {
            const { cx, cy, r } = shape;
            const r2 = r * r;
            for (let py = 0; py < height; py++) {
                for (let px = 0; px < width; px++) {
                    const dx = px - cx;
                    const dy = py - cy;
                    if (dx * dx + dy * dy <= r2) {
                        count++;
                        const idx = (py * width + px) * 3;
                        canvas[idx] = blend(idx, sR, canvas[idx]);
                        canvas[idx + 1] = blend(idx + 1, sG, canvas[idx + 1]);
                        canvas[idx + 2] = blend(idx + 2, sB, canvas[idx + 2]);
                    }
                }
            }
        } else if (type === 'triangle') {
            const pts = shape.points;
            for (let py = 0; py < height; py++) {
                for (let px = 0; px < width; px++) {
                    const v0 = (pts[1][0] - pts[0][0]) * (py - pts[0][1]) - (pts[1][1] - pts[0][1]) * (px - pts[0][0]);
                    const v1 = (pts[2][0] - pts[1][0]) * (py - pts[1][1]) - (pts[2][1] - pts[1][1]) * (px - pts[1][0]);
                    const v2 = (pts[0][0] - pts[2][0]) * (py - pts[2][1]) - (pts[0][1] - pts[2][1]) * (px - pts[2][0]);
                    if ((v0 >= 0 && v1 >= 0 && v2 >= 0) || (v0 <= 0 && v1 <= 0 && v2 <= 0)) {
                        count++;
                        const idx = (py * width + px) * 3;
                        canvas[idx] = blend(idx, sR, canvas[idx]);
                        canvas[idx + 1] = blend(idx + 1, sG, canvas[idx + 1]);
                        canvas[idx + 2] = blend(idx + 2, sB, canvas[idx + 2]);
                    }
                }
            }
        } else if (type === 'line') {
            const { x1, y1, x2, y2, r } = shape;
            const dx = x2 - x1;
            const dy = y2 - y1;
            const L = dx * dx + dy * dy;
            const r2 = r * r;
            for (let py = 0; py < height; py++) {
                for (let px = 0; px < width; px++) {
                    let covered = false;
                    const t = (px - x1) * dx + (py - y1) * dy;
                    if (L === 0) {
                        if ((px - x1) * (px - x1) + (py - y1) * (py - y1) <= r2) covered = true;
                    } else if (t <= 0) {
                        if ((px - x1) * (px - x1) + (py - y1) * (py - y1) <= r2) covered = true;
                    } else if (t >= L) {
                        if ((px - x2) * (px - x2) + (py - y2) * (py - y2) <= r2) covered = true;
                    } else {
                        const c = (px - x1) * dy - (py - y1) * dx;
