                        canvas[idx] = blend(idx, sR, canvas[idx]);
                        canvas[idx + 1] = blend(idx + 1, sG, canvas[idx + 1]);
                        canvas[idx + 2] = blend(idx + 2, sB, canvas[idx + 2]);
                    }
                }
            }
        }
        results.push(`${i + 1} ${type} ${count}`);
    }

