/**
 * A complete TypeScript program to decode Protocol Buffers binary messages 
 * using a .proto schema and print them as JSON.
 */

// --- Types and Interfaces ---

interface FieldDefinition {
  name: string;
  type: string;
  number: number;
  label: 'repeated' | 'optional' | 'singular';
  oneofName: string | null;
  isMap: boolean;
}

interface EnumDefinition {
  name: string;
  values: Map<number, string>;
}

interface MessageDefinition {
  name: string;
  fields: Map<number, FieldDefinition>;
  nestedMessages: Map<string, MessageDefinition>;
  nestedEnums: Map<string, EnumDefinition>;
  oneofs: Map<string, string[]>; // name -> field names
  enums: Map<string, EnumDefinition>;
}

type DecodedValue = any;

class DecodedMessage {
  fields = new Map<number, any>();
  oneofs = new Map<string, number>();
  presence = new Set<number>();
}

// --- Lexer and Parser for .proto ---

class ProtoParser {
  private tokens: string[] = [];
  private pos = 0;

  constructor(private input: string) {
    // Simple tokenizer: split by whitespace, but keep symbols and strings together.
    // This is a simplified tokenizer for the specific subset of proto3.
    this.tokens = input
      .replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*\n?/g, '') // Remove comments
      .replace(/([{}();=,]|[a-zA-Z_][a-zA-Z0-9_]*|[0-9]+|"[^"]*")/g, (match) => match)
      .split(/\s+/)
      .filter(t => t.length > 0);
  }

  private peek() { return this.tokens[this.pos]; }
  private consume() { return this.tokens[this.pos++]; }
  private consumeString() {
    const s = this.consume();
    return s.substring(1, s.length - 1);
  }

  parse() {
    const messages: MessageDefinition[] = [];
    const enums: EnumDefinition[] = [];

    while (this::pos < this.tokens.length) {
      const token = this.peek();
      if (token === 'syntax' || token === 'package' || token === 'option') {
        this.pos += 2; // skip 'syntax = "proto3";' etc.
        if (this.peek() === ';') this.pos++;
        continue;
      }
      if (token === 'message') {
        const msg = this.parseMessage();
        messages.push(msg);
      } else if (token === 'enum') {
        const en = this.parseEnum();
        enums.push(en);
      } else {
        this.pos++;
      }
    }
    return { messages, enums };
  }

  private parseMessage(): MessageDefinition {
    this.consume(); // message
    const name = this.consume();
    const msg: MessageDefinition = {
      name,
      fields: new Map(),
      nestedMessages: new Map(),
      nestedEnums: new Map(),
      oneofs: new Map(),
      enums: new Map()
    };
    this.consume(); // {
    while (this.peek() !== '}') {
      const token = this.peek();
      if (token === 'message') {
        const nested = this.parseMessage();
        msg.nestedMessages.set(nested.name, nested);
      } else if (token === 'enum') {
        const nested = this.parseEnum();
        msg.nestedEnums.set(nested.name, nested);
      } else if (token === 'oneof') {
        this.parseOneof(msg);
      } else if (token === 'reserved') {
        this.consume(); // reserved
        while (this.peek() !== ';') this.consume();
        this.consume(); // ;
      } else {
        this.parseField(msg);
      }
    }
    this.consume(); // }
    return msg;
  }

  private parseEnum(): EnumDefinition {
    this.consume(); // enum
    const name = this.consume();
    const en: EnumDefinition = { name, values: new Map() };
    this.consume(); // {
    while (this.peek() !== '}') {
      const valName = this.consume();
      this.consume(); // =
      const valNum = parseInt(this.consume());
      en.values.set(valNum, valName);
      this.consume(); // ;
    }
    this.consume(); // }
    return en;
  }

  private parseOneof(msg: MessageDefinition) {
    this.consume(); // oneof
    const name = this.consume();
    const fieldNames: string[] = [];
    this.consume(); // {
    while (this.peek() !== '}') {
      const type = this.consume();
      const fieldName = this.consume();
      this.consume(); // =
      const fieldNum = parseInt(this.consume());
      this.consume(); // ;
      fieldNames.push(fieldName);
      msg.fields.set(fieldNum, { name: fieldName, type, number: fieldNum, label: 'singular', oneofName: name, isMap: false });
    }
    this.consume(); // }
    msg.oneofs.set(name, fieldNames);
  }

  private parseField(msg: MessageDefinition) {
    let label: 'repeated' | 'optional' | 'singular' = 'singular';
    let type = '';
    let name = '';
    let number = 0;

    const token = this.peek();
    if (token === 'repeated' || token === 'optional') {
      label = token as any;
      type = this.consume();
    } else {
      type = this.consume();
    }

    // Handle map syntax: map<key, value> name = number;
    if (type.startsWith('map<')) {
      const keyType = type.substring(4, type.indexOf('>'));
      const valueType = type.substring(type.indexOf('>') + 1);
      type = 'map'; // special type
      name = this.consume();
      this.consume(); // =
      number = parseInt(this.consume());
      this.consume(); // ;
      msg.fields.set(number, { name, type: `${keyType},${valueType}`, number, label: 'singular', oneofName: null, isMap: true });
      return;
    }

    name = this.consume();
    this.consume(); // =
    number = parseInt(this.consume());
    this.consume(); // ;

    msg.fields.set(number, { name, type, number, label, oneofName: null, isMap: false });
  }
}

