  private offset = 0;

  readVarint(): bigint {
    let result = 0n;
    let shift = 0n;
    while (true) {
      const b = this.buffer[this.offset++];
      result |= (BigInt(b & 0x7F) << shift);
      if ((b & 0x80) === 0) break;
      shift += 7n;
    }
    return result;
  }

  readFixed32(): number {
    const res = this.buffer.readUInt32LE(this.offset);
    this.offset += 4;
    return res;
  }

  readFixed64(): bigint {
    const res = this.buffer.readBigUInt64LE(this.offset);
    this.offset += 8;
    return res;
  }

  readBytes(): Buffer {
    const len = Number(this.readVarint());
    const res = this.buffer.slice(this.offset, this.offset + len);
    this.offset += len;
    return res;
  }

  readRemaining(): Buffer {
    return this.buffer.slice(this.offset);
  }

  eof() { return this.offset >= this.buffer.length; }
}

