import java.io.*;
import java.math.BigInteger;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dataDir = args[0];
        String baseUrl = args[1];

        String clientJson = Files.readString(Path.of(dataDir, "client.json"));
        Map<String, Object> client = parseJson(clientJson);
        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = (int) client.get("page_size");

        HttpClient client = HttpClient.newBuilder().build();
        String accessToken = getAccessToken(baseUrl, clientId, clientSecret, scope, client);
        int tokenCount = 1;

        int N = 0, P = 0, R = 0, A = 0;
        List<ResultLine> results = new ArrayList<>();
        Map<String, Integer> statusCounts = new TreeMap<>();
        String nextCursor = null;

        while (true) {
            String currentUrl = baseUrl + "/orders?limit=" + pageSize;
            if (nextCursor != null) {
                currentUrl += "&cursor=" + URLEncoder.encode(nextCursor, StandardCharsets.UTF_8);
            }

            HttpRequest request = HttpRequest.newBuilder()
                    .uri(URI.create(currentUrl))
                    .header("Authorization", "Bearer " + accessToken)
                    .GET()
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            int status = response.statusCode();

            if (status == 200) {
                P++;
                Map<String, Object> body = parseJson(response.body());
                List<Map<String, Object>> data = (List<Map<String, Object>>) body.get("data");
                for (Map<String, Object> order : data) {
                    N++;
                    String statusStr = (String) order.get("status");
                    statusCounts.merge(statusStr, 1, Integer::sum);
                    Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                    String name = (String) customer.get("name");
                    String currency = (String) order.get("currency");
                    String amountStr = (String) order.get("amount");
                    if (!"cancelled".equals(statusStr)) {
                        results.add(new ResultLine(name, currency, parseAmountToCents(amountStr)));
                    }
                }
                nextCursor = (String) body.get("next_cursor");
                if (nextCursor == null) break;
            } else if (status == 429 || status == 503) {
                R++;
                if (status == 429) {
                    String retryAfter = response.headers().firstValue("Retry-After").orElse("0");
                    try {
                        Thread.sleep(Integer.parseInt(retryAfter) * 1000L);
                    } catch (NumberFormatException e) {}
                } else {
                    Thread.sleep(1000);
                }
                continue;
            } else if (status == 401) {
                if (tokenCount == 1) {
                    System.out.println("ERROR " + status + " " + response.body());
                    System.exit(0);
                }
                accessToken = getAccessToken(baseUrl, clientId, clientSecret, scope, client);
                tokenCount = 1;
                A++;
                continue;
            } else {
                System.out.println("ERROR " + status + " " + response.body());
                System.exit(0);
            }
        }

        Collections.sort(results);
        for (ResultLine rl : results) {
            System.out.println("total " + rl.currency + " " + rl.formatAmount() + " " + rl.name);
        }
        for (Map.Entry<String, Integer> entry : statusCounts.entrySet()) {
            System.out.println("status " + entry.getKey() + " " + entry.getValue());
        }
        System.out.println("orders " + N + " pages " + P + " retries " + R + " reauth " + A);
    }

    static class ResultLine implements Comparable<ResultLine> {
        String name;
        String currency;
        BigInteger cents;

        ResultLine(String name, String currency, BigInteger cents) {
            this.name = name;
            this.currency = currency;
            this.cents = cents;
        }

        @Override
        public int compareTo(ResultLine other) {
            int cmp = compareUTF8(this.name, other.name);
            if (cmp != 0) return cmp;
            return this.currency.compareTo(other.currency);
        }

        private int compareUTF8(String s1, String s2) {
            byte[] b1 = s1.getBytes(StandardCharsets.UTF_8);
            byte[] b2 = s2.getBytes(StandardCharsets.UTF_8);
            int len = Math.min(b1.length, b2.length);
            for (int i = 0; i < len; i++) {
                int v1 = b1[i] & 0xFF;
                int v2 = b2[i] & 0xFF;
                if (v1 != v2) return v1 - v2;
            }
            return b1.length - b2.length;
        }

        public String formatAmount() {
            boolean negative = cents.signum() < 0;
            BigInteger absCents = cents.abs();
            BigInteger whole = absCents.divide(new BigInteger("100"));
            BigInteger frac = absCents.remainder(new BigInteger("100"));
            return (negative ? "-" : "") + whole.toString() + "." + String.format("%02d", frac.intValue());
        }
    }

    static String getAccessToken(String baseUrl, String clientId, String clientSecret, String scope, HttpClient client) throws Exception {
        String encodedId = specialEncode(clientId);
        String encodedSecret = specialEncode(clientSecret);
        String auth = encodedId + ":" + encodedSecret;
        String encodedAuth = Base64.getEncoder().encodeToString(auth.getBytes(StandardCharsets.UTF_8));
        String body = "grant_type=client_credentials&scope=" + URLEncoder.encode(scope, StandardCharsets.UTF_8);
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/oauth/token"))
                .header("Authorization", "Basic " + encodedAuth)
                .header("Content-Type", "application/x-www-form-urlencoded")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        if (response.statusCode() != 200) {
            System.out.println("ERROR " + response.statusCode() + " " + responses.body()); // wait, response.body()
            System.exit(0);
        }
        return (String) parseJson(response.body()).get("access_token");
    }

    private static String specialEncode(String s) {
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            if ((b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') || 
                b == '-' || b == '.' || b == '_' || b == '*') {
                sb.append((char) b);
            } else if (b == ' ') {
                sb.append('+');
            } else {
                sb.append(String.format("%%%02X", b));
            }
        }
        return sb.toString();
    }

    private static BigInteger parseAmountToCents(String amountStr) {
        boolean negative = amountStr.startsWith("-");
        String absStr = negative ? amountStr.substring(1) : amountStr;
        String[] parts = absStr.split("\\.", 2);
        String wholeStr = parts[0].isEmpty() ? "0" : parts[0];
        BigInteger cents = new BigeInteger(wholeStr).multiply(new BigInteger("100"));
        if (parts.length > 1) {
            String fracStr = parts[1];
            if (fracStr.length() >= 2) {
                cents = cents.add(new BigInteger(fracStr.substring(0, 2)));
            } else if (fracStr.length() == 1) {
                cents = cents.add(new BigInteger(fracStr).multiply(new BigInteger("10")));
            }
        }
        return negative ? cents.negate() : cents;
    }

    // A simple JSON parser for the given structure
    private static Map<String, Object> parseJson(String json) {
        return new JsonParser(json).parseObject();
    }

    static class JsonParser {
        String input;
        int pos = 0;
        JsonParser(String input) { this.input = input; }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos = input.indexOf('{', pos) + 1;
            while (pos < input.length() && input.charAt(pos) != '}') {
                String key = parseString();
                pos = input.indexOf(':', pos) + 1;
                Object value = parseValue();
                map.put(key, value);
                if (input.charAt(pos) == ',') pos++;
                else if (input.charAt(pos) == '}') break;
                skipWS();
            }
            return map;
        }

        private void skipWS() {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) pos++;
        }

        private String parseString() {
            skipWS();
            int start = input.indexOf('"', pos) + 1;
            int end = start;
            while (end < input.length()) {
                if (input.charAt(end) == '"' && input.charAt(end - 1) != '\\') break;
                end++;
            }
            String s = input.substring(start, end);
            pos = end + 1;
            return s.replace("\\\"", "\"").replace("\\\\", "\\");
        }

        private Object parseValue() {
            skipWS();
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') {
                List<Object> list = new ArrayList<>();
                pos = input.indexOf('[', pos) + 1;
                while (input.charAt(pos) != ']') {
                    list.add(parseValue());
                    if (input.charAt(pos) == ',') pos++;
                    skipWS();
                }
                pos++;
                return list;
            }
            if (c == '"') return parseString();
            // For simplicity, handle numbers/booleans/null as strings
            int start = pos;
            while (pos < input.length() && input.charAt(pos) != ',' && input.charAt(pos) != '}' && input.charAt(pos) != ']' && input.charAt(pos) != ' ') {
                pos++;
            }
            String val = input.substring(start, pos);
            if (val.equals("true")) return true;
            if (val.equals("false")) return false;
            if (val.equals("null")) return null;
            try { return Double.parseDouble(val); } catch (Exception e) { return val; }
        }
    }
}

