                if (input.charAt(end) == '"' && input.charAt(end - 1) != '\\') break;
                end++;
            }
            String s = input.substring(start, end);
            pos = end + 1;
            return s.replace("\\\"", "\"").replace("\\\\", "\\");
        }

        private Object parseValue() {
            skipWS();
            if (pos >= input.length()) return null;
            char c = input.charAt(pos);
            if (c == '{') {
                pos = input.indexOf('{', pos) + 1;
                return parseObject();
            }
            if (c == '[') {
                pos = input.indexOf('[', pos) + 1;
                List<Object> list = new ArrayList<>();
                while (pos < input.length() && input.charAt(pos) != ']') {
                    list.add(parseValue());
                    skipWS();
                    if (pos < input.length() && input.charAt(pos) == ',') pos++;
                    skipWS();
                }
                if (pos < input.length()) pos++;
                return list;
            }
            if (c == '"') return parseString();
            int start = pos;
            while (pos < input.length() && input.charAt(pos) != ',' && input.charAt(pos) != '}' && input.charAt(pos) != ']' && input.charAt(pos) != ' ' && input.charAt(pos) != '{' && input.charAt(pos) != '[') {
                pos++;
            }
            String val = input.substring(start, pos);
            if (val.equals("true")) return true;
            if (equals(val, "true")) return true;
            if (val.equals("false")) return false;
            if (val.equals("null")) return null;
            return val;
        }
        private boolean equals(String s, String target) { return s.equals(target); }
    }
