function formUrlEncode(s: string): string {
    const bytes = Buffer.from(s, 'utf8');
    let result = "";
    for (let i = 0; i < bytes.length; i++) {
        const b = bytes[i];
        const c = String.fromCharCode(b);
        if (/[a-zA-Z0-9\-._*]/.test(c)) {
            result += c;
        } else if (c === ' ') {
            result += '+';
        } else {
            result += '%' + b.toString(16).toUpperCase().padStart(2, '0');
        }
    }
    return result;
}

function parseAmount(s: string): bigint {
    const isNegative = s.startsWith('-');
    const abs = isNegative ? s.slice(1) : s;
    const parts = abs.split('.');
    const intVal = BigInt(parts[0] || '0');
    let cents: bigint;
    if (parts.length === 1) {
        cents = intVal * 100n;
    } else {
        const fracStr = parts[1] || '';
        if (fracStr.length === 0) {
            cents = intVal * 100n;
        } else if (fracStr.length === 1) {
            cents = intVal * 100n + BigInt(fracStr) * 10n;
        } else {
            cents = intVal * 100n + BigInt(fracStr.substring(0, 2));
        }
    }
    return isNegative ? -cents : cents;
}

function formatAmount(cents: bigint): string {
    const isNegative = cents < 0n;
    const absCents = isNegative ? -cents : cents;
    const integerPart = absCents / 100n;
    const fractionalPart = absCents % 100n;
    const sign = isNegative ? "-" : "";
    return `${sign}${integerPart.toString()}.${fractionalPart.toString().padStart(2, '0')}`;
}

