// MARK: - Helpers
func formUrlEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        let char = Character(UnicodeScalar(byte)!)
        if (char >= "a" && char <= "z") || (char >= "A" && char <= "Z") || (char >= "0" && char <= "9") || "-._*".contains(char) {
            result.append(char)
        } else if char == " " {
            result.append("+")
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

func parseAmount(_ s: String) -> Int64 {
    let isNegative = s.hasPrefix("-")
    let absolute = isNegative ? String(s.dropFirst()) : s
    let parts = absolute.split(separator: ".")
    var cents: Int64 = 0
    if parts.count == 1 {
        cents = (Int64(parts[0]) ?? 0) * 100
    } else {
        let integerPart = Int64(parts[0]) ?? 0
        let fracStr = String(parts[1])
        var fracVal = Int64(fracStr) ?? 0
        if fracStr.count == 1 {
            fracVal *= 10
        }
        cents = integerPart * 100 + fracVal
    }
    return isNegative ? -cents : cents
}

func formatAmount(_ cents: Int64) -> String {
    let isNegative = cents < 0
    let absCents = abs(cents)
    let integerPart = absCents / 100
    let fractionalPart = absCents % 100
    let sign = isNegative ? "-" : ""
    return "\(sign)\(integerPart).\(String(format: "%02d", fractionalPart))"
}

func percentEncodeCursor(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        let char = Character(UnicodeScalar(byte)!)
        if (char >= "a" && char <= "z") || (char >= "A" && char <= "Z") || (char >= "0" && char <= "9") || "-._~".contains(char) {
            result.append(char)
        } else {
            result.append(String(format: "%%%02X", byte))
        }
    }
    return result
}

