fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        return;
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    let client_json = std::fs::read_to_string(format!("{}/client.json", data_dir)).unwrap();
    let client_id = get_json_value(&client_json, "client_id").unwrap();
    let client_secret = get_json_value(&client_json, "client_secret").unwrap();
    let scope = get_json_value(&client_json, "scope").unwrap();
    let page_size = get_json_value(&client_json, "page_size").unwrap().parse::<u32>().unwrap();

    let (host_port, path_prefix) = parse_url(base_url);

    let mut access_token = get_token(&host_port, &path_prefix, &client_id, &client_secret, &scope).unwrap();
    let mut is_first_order_request = true;

    let mut orders_count = 0u64;
    let mut pages_count = 0u64;
    let mut retries_count = 0u64;
    let mut reauth_count = 0u64;

    let mut customer_currency_map: Vec<(String, String, i64)> = Vec::new();
    let mut status_counts: HashMap<String, u64> = HashMap::new();

    let mut next_cursor: Option<String> = None;

    loop {
        let (method, path, body) = if let Some(ref cursor) = next_cursor {
            ("GET", format!("{}/orders?limit={}&cursor={}", path_prefix, page_size, percent_encode_for_query(cursor)), None)
        } else {
            ("GET", format!("{}/orders?limit={}", path_prefix, page_size), None)
        };

        let mut request_headers = vec![
            ("Host".to_string(), host_port.clone()),
            ("Connection".to_string(), "close".to_string()),
            ("Authorization".to_string(), format!("Bearer {}", access_token)),
        ];

        if method == "POST" {
            request_headers.push(("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()));
        }

        let (status, response_body) = match make_request(&host_port, &method, &path, &request_headers, body.clone().unwrap_or_default()) {
            Ok(res) => res,
            Err(e) => {
                println!("ERROR {} {}", e.0, e.1);
                return;
            }
        };

        if status == 200 {
            pages_count += 1;
            is_first_order_request = false;

            let json = parse_json_to_map(&response_body);
            if let Some(data_val) = json.get("data") {
                if let Json::Array(orders) = data_val {
                    for order_json in orders {
                        orders_count += 1;
                        if let Json::Object(order_map) = order_json {
                            let status_str = order_map.get("status").and_then(|v| v.as_string()).cloned().unwrap_or_default();
                            *status_counts.entry(status_str.clone()).or_insert(0) += 1;

                            if status_str != "cancelled" {
                                if let Some(customer_obj) = order_map.get("customer").and_then(|v| v.as_object()) {
                                    let name = customer_obj.get("name").and_then(|v| v.as_string()).cloned().unwrap_or_default();
                                    let currency = order_map.get("currency").and_then(|v| v.as_string()).cloned().unwrap_or_default();
                                    let amount_str = order_map.get("amount").and_then(|v| v.as_string()).cloned().unwrap_or_default();
                                    let amount_cents = parse_amount(&amount_str);
                                    customer_currency_map.push((name, currency, amount_cents));
                                }
                            }
                        }
                    }
                }
            }

            if let Some(cursor_val) = json.get("next_cursor") {
                if let Json::String(cursor_str) = cursor_val {
                    if !cursor_str.is_empty() {
                        next_cursor = Some(cursor_str.clone());
                    } else {
                        next_cursor = None;
                    }
                } else {
                    next_cursor = None;
                }
            } else {
                next_cursor = None;
            }
        } else if status == 429 {
            retries_count += 1;
            let retry_after = response_body.split_whitespace().nth(1).and_then(|s| s.parse::<u64>().ok()).unwrap_or(1);
            std::thread::sleep(std::time::Duration::from_secs(retry_after));
            continue;
        } else if status == 503 {
            retries_count += 1;
            std::thread::sleep(std::time::Duration::from_millis(1000));
            continue;
        } else if status == 401 {
            if is_first_order_request {
                println!("ERROR 401 {}", response_body);
                return;
            }
            reauth_count += 1;
            access_token = get_token(&host_port, &path_prefix, &client_id, &client_secret, &scope).unwrap();
            is_first_order_request = true;
            continue;
        } else {
            println!("ERROR {} {}", status, response_body);
            return;
        }

        if next_cursor.is_none() { break; }
    }

    let mut final_totals: Vec<(String, String, i64, String)> = Vec::new();
    let mut totals_map: HashMap<(String, String), i64> = HashMap::new();
    for (name, currency, amount) in customer_currency_map {
        let entry = totals_map.entry((name.clone(), currency.clone())).or_insert(0);
        *entry += amount;
    }
    for (key, amount) in totals_map {
        final_totals.push((key.1.clone(), key.0.clone(), amount, key.1.clone()));
    }
    // Wait, the grouping is (name, currency). Let's re-sort.
    // Actually, let's just use the map.
