    for (key, amount) in totals_map {
        results.push((key.1.clone(), key.0.clone(), amount, key.1.clone()));
    }
    // Corrected:
    let mut final_output: Vec<String> = Vec::new();
    let mut sorted_totals: Vec<(String, String, i64, String)> = Vec::new();
    for (key, amount) in totals_map {
        sorted_totals.push((key.1.clone(), key.0.clone(), amount, key.1.clone()));
    }
    // Sort by name, then currency
    sorted_totals.sort_by(|a, b| {
        let cmp_name = a.1.cmp(&b.1);
        if cmp_name != std::cmp::Ordering::Equal { cmp_name } else { a.0.cmp(&b.0) }
    });

    for (currency, name, amount, _) in sorted_totals {
        let sign = if amount < 0 { "-" } else { "" };
        let abs_cents = amount.abs();
        let integer_part = abs_cents / 100;
        let fractional_part = abs_cents % 100;
        println!("total {} {}{}.{:02} {}", currency, sign, integer_part, fractional_part, name);
    }

    let mut status_vec: Vec<(String, u64)> = status_counts.into_iter().collect();
    status_vec.sort_by(|a, b| a.0.cmp(&b.0));
    for (status, count) in status_vec {
        println!("status {} {}", status, count);
    }

    println!("orders {} pages {} retries {} reauth {}", orders_count, pages_count, retries_count, reauth_count);
}

fn parse_url(url: &str) -> (String, String) {
    let host_port = url.split('/').nth(2).unwrap_or("").to_string();
    let path_prefix = if let Some(p) = url.splitn(4, '/').nth(3) {
        format!("/{}", p)
    } else {
        "".to_string()
    };
    (host_host_port_fix(url), path_prefix)
}

fn host_host_port_fix(url: &str) -> String {
    let parts: Vec<&str> = url.splitn(2, '/').collect();
    let host_port = parts[0].replace("http://", "").replace("https://", "");
    host_port
}

