#[derive(Debug, Clone)]
enum Json {
    Object(HashMap<String, Json>),
    Array(Vec<Json>),
    String(String),
    Number(String),
    Null,
}

impl Json {
    fn as_string(&self) -> Option<&String> {
        if let Json::String(s) = self { Some(s) } else { None }
    }
    fn as_object(&self) -> Option<&HashMap<String, Json>> {
        if let Json::Object(m) = self { Some(m) } else { None }
    }
    fn as_array(&self) -> Option<&Vec<Json>> {
        if let Json::Array(a) = self { Some(a) } else { None }
    }
}

fn parse_json_to_map(s: &str) -> HashMap<String, Json> {
    let json = parse_json(s);
    json.as_object().cloned().unwrap_or_default()
}

fn parse_json(s: &str) -> Json {
    let mut chars = s.chars().peekable();
    parse_value(&mut chars).unwrap_or(Json::Null)
}

fn parse_value(chars: &mut std::iter::Peekable<std::str::Chars>) -> Option<Json> {
    skip_whitespace(chars);
    let c = match chars.peek() {
        Some(&c) => c,
        None => return None,
    };

    if c == '{' {
        parse_object(chars)
    } else if c == '[' {
        parse_array(chars)
    } else if c == '"' {
        parse_string(chars)
    } else if c == 'n' {
        for _ in 0..4 { chars.next(); }
        Some(Json::Null)
    } else if c == 't' {
        for _ in 0..4 { chars.next(); }
        Some(Json::String("true".to_string()))
    } else if c == 'f' {
        for _ in 0..5 { chars.next(); }
        Some(Json::String("false".to_string()))
    } else {
        parse_primitive(chars)
    }
}

fn skip_whitespace(chars: &mut std::iter::Peekable<std::str::Chars>) {
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() {
            chars.next();
        } else {
            break;
        }
    }
}

fn parse_object(chars: &mut std::iter::Peekable<std::str::Chars>) -> Option<Json> {
    chars.next(); // {
    let mut map = HashMap::new();
    loop {
        skip_whitespace(chars);
        if let Some(&'}') = chars.peek() {
            chars.next();
            return Some(Json::Object(map));
        }
        let key = match parse_string(chars) {
            Some(s) => s,
            None => return None,
        };
        skip_whitespace(chars);
        if let Some(':') = chars.next() {
            // skip colon
        }
        let val = parse_value(chars).unwrap_or(Json::Null);
        map.insert(key, val);
        skip_whitespace(chars);
        if let Some(',') = chars.peek() {
            chars.next();
        }
    }
}

fn parse_array(chars: &mut std::iter::Peekable<std::str::Chars>) -> Option<Json> {
    chars.next(); // [
    let mut arr = Vec::new();
    loop {
        skip_whitespace(chars);
        if let Some(&']') = chars.peek() {
            chars.next();
            return Some(Json::Array(arr));
        }
        let val = parse_value(chars).unwrap_or(Json::Null);
        arr.push(val);
        skip_whitespace(chars);
        if let Some(',') = chars.peek() {
            chars.next();
        }
    }
}

fn parse_string(chars: &mut std::iter::Peekable<std::str::Chars>) -> Option<String> {
    chars.next(); // "
    let mut s = String::new();
    while let Some(c) = chars.next() {
        if c == '"' {
            return Some(s);
        } else if c == '\\' {
            if let Some(esc) = chars.next() {
                s.push(esc);
            }
        } else {
            s.push(c);
        }
    }
    Some(s)
}

fn parse_primitive(chars: &mut std::iter::Peekable<std::str::Chars>) -> Option<Json> {
    let mut s = String::new();
    while let Some(&c) = chars.peek() {
        if c.is_whitespace() || c == ',' || c == '}' || c == ']' {
            break;
        }
        s.push(chars.next().unwrap());
    }
    if s == "true" { Some(Json::String("true".to_string())) }
    else if s == "false" { Some(Json::String("false".to_string())) }
    else if s == "null" { Some(Json::Null) }
    else { Some(Json::Number(s)) }
}

