fn get_json_value(json: &str, key: &str) -> Option<String> {
    let parsed = parse_json(json);
    if let Json::Object(map) = parsed {
        if let Some(val) = map.get(key) {
            return match val {
                Json::String(s) => Some(s.clone()),
                Json::Number(s) => Some(s.clone()),
                _ => None,
            };
        }
    }
    None
}

fn get_token(host_port: &str, path: &str, client_id: &str, client_secret: &str, scope: &str) -> Option<String> {
    let auth_str = format!("{}:{}", percent_encode_for_auth(client_id), percent_encode_for_auth(client_secret));
    let auth_b64 = base64_encode(auth_str.as_bytes());
    let body = format!("grant_type=client_credentials&scope={}", percent_encode_for_query(scope));

    let mut headers = vec![
        ("Host".to_string(), host_port.to_string()),
        ("Content-Type".to_string(), "application/x-www-form-urlencoded".to_string()),
        ("Authorization".to_string(), format!("Basic {}", auth_b64)),
    ];

    let (status, body_res) = make_request(host_port, "POST", path, &headers, body);
    if status == 200 {
        let json = parse_json(&body_res);
        if let Json::Object(map) = json {
            if let Some(Json::String(token)) = map.get("access_token") {
                return Some(token.clone());
            }
        }
    }
    None
}

fn percent_encode_for_auth(s: &str) -> String {
    let mut res = String::new();
    for b in s.as_bytes() {
        match b {
            b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'*' => {
                res.push(*b as char);
            }
            b' ' => res.push('+'),
            _ => {
                res.push('%');
                res.push_str(&format!("{:02X}", b));
            }
        }
    }
    res
}

fn percent_encode_for_query(s: &str) -> String {
    let mut res = String::new();
    for b in s.as_bytes() {
        match b {
            b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                res.push(*b as char);
            }
            _ => {
                res.push('%');
                res.push_str(&format!("{:02X}", b));
            }
        }
    }
    res
}

fn base64_encode(input: &[u8]) -> String {
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut res = String::new();
    let mut i = 0;
    while i < input.len() {
        let b1 = input[i] as u32;
        let b2 = if i + 1 < input.len() { input[i+1] as u32 } else { 0 };
        let b3 = if i + 2 < input.len() { input[i+2] as u32 } else { 0 };
        let chunk = (b1 << 16) | (b2 << 8) | b3;
        res.push(alphabet[((chunk >> 18) & 0x3F) as usize] as char);
        res.push(alphabet[((chunk >> 12) & 0x3F) as usize] as char);
        if i + 1 < input.len() {
            res.push(alphabet[((chunk >> 6) & 0x3F) as usize] as char);
        } else {
            res.push('=');
        }
        if i + 2 < input.len() {
            res.push(alphabet[(chunk & 0x3F) as usize] as char);
        } else {
            res.push('=');
        }
        i += 3;
    }
    res
}

fn make_request(host_port: &str, method: &str, path: &str, headers: &[ (String, String) ], body: String) -> Result<(u32, String), (u32, String)> {
    let mut stream = TcpStream::connect(host_port).map_err(|_| (0, "".to_string()))?;
    let request = format!(
        "{} {} HTTP/1.1\r\n{}\r\n\r\n{}",
        method, path,
        headers.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().join("\r\n"),
        body
    );
    stream.write_all(request.as_bytes()).unwrap();

    let mut response = String::new();
    let mut buffer = [0u8; 8192];
    let mut total_read = 0;

    // This is a simplified reader for the single-line JSON requirement
    let mut head_buf = Vec::new();
    let mut body_buf = Vec::new();

    // We need to parse the response properly.
    // Let's read the whole thing and then split.
    let mut full_response = Vec::new();
    loop {
        let n = stream.read(&mut buffer).unwrap_or(0);
        if n == 0 { break; }
        full_response.extend_from_slice(&buffer[..n]);
    }

    let full_str = String::from_utf8_lossy(&full_response);
    let parts: Vec<&str> = full_str.splitn(2, "\r\n\r\n").collect();
    if parts.len() < 2 { return Err((0, "".to_string())); }

    let header_part = parts[0];
    let body_part = parts[1];

    let mut status = 0;
    if let Some(line) = header_part.lines().next() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            status = parts[1].parse::<u32>().unwrap_or(0);
        }
    }

    // Handle chunked encoding if necessary
    let final_body = if header_part.contains("Transfer-Encoding: chunked") {
        // For simplicity, since the body is a single line of JSON, 
        // we'll assume the body_part contains the JSON.
        // In a real-world scenario, we'd parse the chunks.
        body_part.split("0\r\n").next().unwrap_or(body_part).trim_end_matches('\r').trim_end_matches('\n').to_string()
    } else {
        body_part.to_string()
    };

    Ok((status, final_body))
}

