        ResponseResult res2 = sendRequest(baseUrl, apiKey, body2);
        printResponse(2, res2.blocks, res2.stopReason, res2.toolResults);
        runTools(res2);

        System.out.printf("usage input=%d output=%d cache_read=%d\n",
                res1.totalInput + res2.totalInput,
                res1.totalOutput + res2.totalOutput,
                res1.totalCache + res2.totalCache);
    }

    static String getToolsRaw(String json) {
        int toolsIdx = json.indexOf("\"tools\":");
        int start = json.indexOf('[', toolsIdx);
        int end = findClosingBracket(json, start);
        return json.substring(start, end + 1);
    }

    static int findClosingBracket(String json, int start) {
        int count = 0;
        for (int i = start; i < json.length(); i++) {
            if (json.charAt(i) == '[') count++;
            else if (json.charAt(i) == ']') {
                count--;
                if (count == 0) return i;
            }
        }
        return -1;
    }

    static String buildBody(String model, int maxTokens, int thinkingBudget, String system, String tools, String prompt) {
        return "{\"model\":" + escapeJson(model) + ",\"max_tokens\":" + maxTokens + ",\"stream\":true,\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":" + thinkingBudget + "},\"system\":" + escapeJson(system) + ",\"tools\":" + tools + ",\"messages\":[{\"role\":\"user\",\"content\":" + escapeJson(prompt) + "}]}";
    }

    static String buildBody2(String model, int maxTokens, int thinkingBudget, String system, String tools, String prompt, List<ContentBlock> blocks, List<String> results) {
        StringBuilder sb = new StringBuilder();
        sb.append("{\"model\":").append(escapeJson(model)).append(",\"max_tokens\":").append(maxTokens)
          .append(",\"stream\":true,\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":").append(thinkingBudget)
          .append("},\"system\":").append(escapeJson(system)).append(",\"tools\":").append(tools)
          .append(",\"messages\":[{\"role\":\"user\",\"content\":").append(escapeJson(prompt)).append("},");

        sb.append("{\"role\":\"assistant\",\"content\":[");
        for (int i = 0; i < blocks.size(); i++) {
            ContentBlock b = blocks.get(i);
            if (b.type.equals("text")) sb.append("{\"type\":\"text\",\"text\":").append(escapeJson(b.text)).append("}");
            else if (b.type.equals("thinking")) sb.append("{\"type\":\"thinking\",\"thinking\":").append(escapeJson(b.thinking)).append(",\"signature\":").append(escapeJson(b.signature)).append("}");
            else if (b.type.equals("tool_use")) sb.append("{\"type\":\"tool_use\",\"id\":").append(escapeJson(b.id)).append(",\"name\":").append(escapeJson(b.name)).append(",\"input\":").append(b.inputJson);
            if (i < blocks.size() - 1) sb.append(",");
        }
        sb.append("],{\"role\":\"user\",\"content\":[");
        for (int i = 0; i < results.size(); i++) {
            String res = results.get(i);
            String[] parts = res.split(" ", 3);
            String type = parts[0];
            String id = parts[1];
            String content = parts[2];
            sb.append("{\"type\":\"tool_result\",\"tool_use_id\":").append(escapeJson(id)).append(",\"content\":").append(escapeJson(content));
            if (type.equals("error")) sb.append(",\"is_error\":true");
            sb.append("}");
            if (i < results.size() - 1) sb.append(",");
        }
        sb.append("]}]}");
        return sb.toString();
    }

    static String escapeJson(String s) {
        if (s == null) return "null";
        StringBuilder sb = new StringBuilder();
        sb.append("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '"') sb.append("\\\"");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        sb.append("\"");
        return sb.toString();
    }

    static class ContentBlock {
        String type, id, name, text, thinking, signature, inputJson;
        int index;
    }

    static class ResponseResult {
        List<ContentBlock> blocks = new ArrayList<>();
        List<String> toolResults = new ArrayList<>();
        String stopReason;
        int totalInput = 0, totalOutput = 0, totalCache = 0;
    }

    static void printResponse(int reqNum, List<ContentBlock> blocks, String stopReason, List<String> toolResults) {
        System.out.println("request " + reqNum);
        for (ContentBlock b : blocks) {
            if (b.type.equals("text")) {
                System.out.print("text " + escape(b.text) + "\n");
            } else if (s_eq(b.type, "thinking")) {
                System.out.print("thinking " + escape(b.text) + "\n");
                System.out.print("signature " + escape(b.signature) + "\n");
            } else if (b.type.equals("tool_use")) {
                System.out.print("tool_use " + escape(b.id) + " " + escape(b.name) + " " + b.inputJson + "\n");
            }
        }
        System.out.println("stop_reason " + stopReason);
        for (String res : toolResults) System.out.println(res);
    }

    static boolean s_eq(String a, String b) { return a != null && a.equals(b); }

    static String escape(String s) {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c;\n            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    static void runTools(ResponseResult res) {
        for (ContentBlock b : res.blocks) {
            if (b.type.equals("tool_use")) {
                res.toolResults.add(executeTool(b));
            }
        }
    }

    static String executeTool(ContentBlock b) {
        SimpleParser sp = new SimpleParser(b.inputJson);
        Map<String, Object> input = (Map<String, Object>) sp.parse();
        String text = (String) input.get("text");
        String unit = (String) input.get("unit");
        if (b.name.equals("measure")) {
            if (unit == null) return "error " + b.id + " unsupported unit: null";
            long count = 0;
            if (unit.equals("code_points")) count = text.codePoints().count();
            else if (unit.equals("utf8_bytes")) count = text.getBytes(StandardCharsets.UTF_8).length;
            else if (unit.equals("utf16_units")) count = text.length();
            else return "error " + b.id + " unsupported unit: " + unit;
            return "result " + b.id + " " + count;
        } else if (b.name.equals("reverse")) {
            int[] cps = text.codePoints().toArray();
            for (int i = 0; i < cps.length / 2; i++) {
                int tmp = cps[i]; cps[i] = cps[cps.length - 1 - i]; cps[cps.length - 1 - i] = tmp;
            }
            StringBuilder sb = new StringBuilder();
            for (int cp : cps) sb.appendCodePoint(cp);
            return "result " + b.id + " " + escape(sb.toString());
        } else return "error " + b.id + " unknown tool: " + b.name;
    }

    static ResponseResult sendRequest(String baseUrl, String apiKey, String body) throws Exception {
        HttpClient client = HttpClient.newBuilder().build();
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/v1/messages"))
                .header("x-api-key", apiKey)
                .header("anthropic-version", "2023-06-01")
                .header("content-type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(body))
                .build();

        HttpResponse<InputStream> response = client.send(request, HttpResponse.BodyHandlers.ofInputStream());
        if (response.statusCode() != 200) {
            // Error handling logic
            return null;
        }
        ResponseResult res = new ResponseResult();
        InputStream is = response.body();
        Scanner scanner = new Scanner(is, StandardCharsets.UTF_8);
        Map<Integer, ContentBlock> blocksMap = new TreeMap<>();
        String currentEvent = "";
        StringBuilder currentData = new StringBuilder();

        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            if (line.startsWith("event:")) {
                currentEvent = line.substring(6).trim();
                currentData.setLength(0);
            } else if (line.startsWith("data:")) {
                String data = line.substring(5).trim();
                if (currentData.length() > s_len_check(currentData)) currentData.append("\n").append(data);
                else currentData.append(data);
            } else if (line.trim().isEmpty()) {
                if (currentData.length() > 0) {
                    processEvent(currentEvent, currentData.toString(), blocksMap, res);
                    currentEvent = ""; currentData.setLength(0);
                }
            }
        }
        if (currentData.length() > 0) processEvent(currentEvent, currentData.toString(), blocksMap, res);
        res.blocks = new ArrayList<>(blocksMap.values());
        res.blocks.sort(Comparator.comparingInt(b -> b.index));
        return res;
    }
    static int s_len_check(StringBuilder sb) { return 0; }

    static void processEvent(String event, String data, Map<Integer, ContentBlock> blocksMap, ResponseResult res) {
        if (event.equals("message_start")) {
            SimpleParser sp = new SimpleParser(data);
            Map<String, Object> usage = (Map<String, Object>) ((Map<String, Object>) sp.parse()).get("usage");
            res.totalInput += Integer.parseInt(usage.get("input_tokens").toString());
            ress_cache_read(res, usage);
        } else if (event.equals("content_block_start")) {
            SimpleParser sp = new SimpleParser(data);
            Map<String, Object> cb = (Map<String, Object>) sp.parse().get("content_block");
            ContentBlock b = new ContentBlock();
            b.type = (String) cb.get("type");
            b.index = (Integer) cb.get("index");
            if (b.type.equals("text")) b.text = (String) cb.get("text");
            else if (b.type.equals("thinking")) {
                b.text = (String) cb.get("thinking");
                b.signature = (String) cb.get("signature");
            } else if (b.type.equals("tool_use")) {
                b.id = (String) cb.get("id");
                b.name = (String) cb.get("name");
                b.inputJson = (String) cb.get("input").toString().replace("{}", ""); // Placeholder
                // The input_json is the raw JSON, but we need to handle the placeholder.
                // Wait, the input_json is built from deltas.
                b.inputJson = "{}"; 
            }
            blocksMap.put(b.index, b);
        } else if (event.equals("content_block_delta")) {
            SimpleParser sp = new SimpleParser(data);
            Map<String, Object> delta = (Map<String, Object>) sp.parse().get("delta");
            int idx = (Integer) delta.get("index");
            ContentBlock b = blocksMap.get(idx);
            if (b.type.equals("text") || b.type.equals("thinking")) {
                String val = (String) delta.get(b.type.equals("text") ? "text_delta" : "thinking_delta");
                if (b.type.equals("thinking") && delta.containsKey("signature_delta")) {
                    b.signature += (String) delta.get("signature_delta");
                } else b.text += val;
            } else if (b.type.equals("tool_use")) {
                b.inputJson += (String) delta.get("partial_json");
            }
        } else if (event.equals("content_block_stop")) {
            int idx = (Integer) ((Map<String, Object>) new SimpleParser(data).parse().get("index"));
            // Just to be safe, we don't remove it, just stop processing it.
        } else if (event.equals("message_delta")) {
            Map<String, Object> delta = (Map<String, Object>) new SimpleParser(data).parse().get("delta");
            res.stopReason = (String) delta.get("stop_reason");
            res.totalOutput += Integer.parseInt(delta.get("usage").toString().split("output_tokens")[0].isEmpty() ? "0" : "0"); // Placeholder
            // The real way:
            res.totalOutput += Integer.parseInt(delta.get("usage").toString().contains("output_tokens") ? 
                               ((Map<String, Object>)delta.get("usage")).get("output_tokens").toString() : "0");
        } else if (event.equals("message_stop")) {
s_end_of_stream();
        }
    }
    static void ress_cache_read(ResponseResult res, Map<String, Object> usage) {
        res.totalCache += Integer.parseInt(usage.get("cache_read_input_tokens").toString());
    }
    static void s_end_of_stream() {}

    static class SimpleParser {
        String json; int pos = 0;
        SimpleParser(String json) { this.json = json; }
        Object parse() {
            skipWhitespace();
            if (pos >= json.length()) return null;
            char c = json.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (Character.isDigit(c) || c == '-') return parseNumber();
            if (c == 't' && json.startsWith("true", pos)) { pos += 4; return true; }
            if (c == 'f' && json.startsWith("false", pos)) { pos += 5; return false; }
            if (c == 'n' && json.startsWith("null", pos)) { pos += 4; return null; }
            return null;
        }
        void skipWhitespace() { while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++; }
        String parseString() {
            StringBuilder sb = new StringBuilder();
            pos++;
            while (pos < json.length()) {
                char c = json.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char esc = json.charAt(pos);
                    if (esc == '"') sb.append('"'); else if (esc == '\\') sb.append('\\');
                    else if (esc == 'n') sb.append('\n'); else if (esc == 'r') sb.append('\r');
                    else if (esc == 't') sb.append('\t');
                    else if (esc == 'u') {
                        sb.append((char) Integer.parseInt(json.substring(pos + 1, pos + 5), 16));
                        pos += 4;
                    } else sb.append(esc);
                    pos++;
                } else { sb.append(c); pos++; }
            }
            return sb.toString();
        }
        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                String key = parseString();
                skipWhitespace(); pos++; skipWhitespace();
                Object val = parse();
                map.put(key, val);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == '}') { pos++; break; }
                pos++; skipWhitespace();
            }
            return map;
        }
        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; skipWhitespace();
            if (pos < json.length() && json.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                Object val = parse();
                list.add(val);
                skipWhitespace();
                if (pos < json.length() && json.charAt(pos) == ']') { pos++; break; }
                pos++; skipWhitespace();
            }
            return list;
        }
        String parseNumber() {
            int start = pos;
            while (pos < json.length() && !"{}[],: \n\r\t\"".contains(String.valueOf(json.charAt(pos)))) pos++;
            return json.substring(start, pos);
        }
    }
}

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.net.http.*;
import java.net.URI;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length < 2) return;
        String dataDir = args[0];
        String baseUrl = args[1];

        String taskJsonStr = Files.readString(Path.of(dataDir, "task.json"), StandardCharsets.UTF_8);
        JsonParser taskParser = new JsonParser(taskJsonStr);
        Map<String, Object> task = (Map<String, Object>) taskParser.parse();

        String inventoryCsvStr = Files.readString(Path.of(dataDir, "inventory.csv"), StandardCharsets.UTF_8);
        if (inventoryCsvStr.startsWith("\uFEFF")) inventoryCsvStr = inventoryCsvStr.substring(1);
        List<List<String>> inventory = parseCsv(inventoryCsvStr);

        String ratesJsonStr = Files.readString(Path.of(dataDir, "rates.json"), StandardCharsets.UTF_8);
        JsonParser ratesParser = new JsonParser(ratesJsonStr);
        Map<String, Object> ratesData = (Map<String, Object>) ratesParser.parse();
        Map<String, Long> rates = new HashMap<>();
        Map<String, Object> ratesMap = (Map<String, Object>) ratesData.get("rates");
        for (Map.Entry<String, Object> entry : ratesMap.entrySet()) {
            rates.put(entry.getKey(), ((Number) entry.getValue()).longValue());
        }

        String apiKey = (String) task.get("api_key");
        String model = (String) task.get("model");
        String system = (String) task.get("system");
        String user = (String) task.get("user");
        List<Object> tools = (List<Object>) task.get("tools");

        List<Map<String, Object>> messages = new ArrayList<>();
        Map<String, Object> sysMsg = new LinkedHashMap<>();
        sysMsg.put("role", "system");
        sysMsg.put("content", system);
        messages.add(sysMsg);
        Map<String, Object> userMsg = new LinkedHashMap<>();
        userMsg.put("role", "user");
        userMsg.put("content", user);
        messages.add(userMsg);

        HttpClient client = HttpClient.newBuilder().build();
        long totalPrompt = 0, totalCompletion =s 0, totalTokens = 0;
        int requests = 0;

        while (true) {
            requests++;
            Map<String, Object> requestBodyMap = new LinkedHashMap<>();
            requestBodyMap.put("model", model);
            requestBodyMap.put("messages", messages);
            requestBodyMap.put("tools", tools);
            requestBodyMap.put("tool_choice", "auto");
            String requestBody = toJson(requestBodyMap);

            HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + "/chat/completions"))
                .header("Authorization", "Bearer " + apiKey)
                .header("Content-Type", "application/json")
                .POST(HttpRequest.BodyPublishers.ofString(requestBody))
                .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() != 200) {
                String errorMessage = "Unknown error";
                try {
                    Map<String, Object> errorMap = (Map<String, Object>) new JsonParser(response.body()).parse();
                    Map<String, Object> error = (Map<String, Object>) errorMap.get("error");
                    errorMessage = (String) error.get("message");
                } catch (Exception e) {}
                System.out.println("ERROR " + response.statusCode() + " " + errorMessage);
                System.exit(0);
            }

            Map<String, Object> res = (Map<String, Object>) new JsonParser(response.body()).parse();
            List<Map<String, Object>> choices = (List<Map<String, Object>>) res.get("choices");
            Map<String, Object> choice = choices.get(0);
            Map<String, Object> message = (Map<String, Object>) choice.get("message");
            String finishReason = (String) choice.get("finish_reason");

            Map<String, Object> usage = (Map<String, Object>) res.get("usage");
            totalPrompt += ((Number) usage.get("prompt_tokens")).longValue();
            totalCompletion += ((Number) usage.get("completion_tokens")).longValue();
            totalTokens += ((Number) usage.get("total_tokens")).longValue();

            if ("tool_calls".equals(finishReason)) {
                Object content = message.get("content");
                if (content != null) System.out.println("SAY " + content);
                messages.add(new LinkedHashMap<>(message));

                List<Map<String, Object>> toolCalls = (List<Map<String, Object>>) message.get("tool_calls");
                for (Map<String, Object> tc : toolCalls) {
                    System.out.println("CALL " + tc.get("id") + " " + ((Map<String, Object>) tc.get("function")).get("name"));
                }

                for (Map<String, Object> tc : toolCalls) {
                    String id = (String) tc.get("id");
                    String name = (String) ((Map<String, Object>) tc.get("function")).get("name");
                    String argsStr = (String) ((Map<String, Object>) tc.get("function")).get("arguments");
                    Map<String, Object> args = (Map<String, Object>) new JsonParser(argsStr).parse();

                    String resultJson = "";
                    if (name.equals("inventory_lookup")) {
                        resultJson = inventoryLookup(inventory, (String) args.get("sku"));
                    } else if (name.equals("convert_currency")) {
                        long amount = ((Number) args.get("amount_cents")).longValue();
                        resultJson = convertCurrency(amount, (String) args.get("from"), (String) args.get("to"), rates);
                    } else {
                        resultJson = "{\"error\":\"unknown tool: " + name + "\"}";
                    }
                    System.out.println("RESULT " + id + " " + resultJson);
                    Map<String, Object> toolMsg = new LinkedHashMap<>();
                    toolMsg.put("role", "tool");
                    toolMsg.put("tool_call_id", id);
                    toolMsg.put("content", resultJson);
                    messages.add(toolMsg);
                }
            } else if ("stop".equals(finishReason)) {
                System.out.println("FINAL " + message.get("content"));
                System.out.println("USAGE prompt=" + totalPrompt + " completion=" + totalCompletion + " total=" + totalTokens + " requests=" + requests);
                break;
            }
        }
    }

    private static List<List<String>> parseCsv(String content) {
        List<List<String>> rows = new ArrayList<>();
        List<String> currentRow = new ArrayList<>();
        StringBuilder currentField = new StringBuilder();
        boolean inQuotes = false;
        for (int i = 0; i < content.length(); i++) {
            char c = content.charAt(i);
            if (inQuotes) {
                if (c == '"') {
                    if (i + 1 < content.length() && content.charAt(i + 1) == '"') {
                        currentField.append('"'); i++;
                    } else inQuotes = false;
                } else currentField.append(c);
            } else {
                if (c == '"') inQuotes = true;
                else if (c == ',') { currentRow.add(currentField.toString()); currentField.setLength(0); }
                else if (c == '\r' || c == '\n') {
                    currentRow.add(currentField.toString());
                    rows.add(new ArrayList<>(currentRow));
                    currentRow.clear(); currentField.setLength(0);
                    if (c == '\r' && i + 1 < content.length() && content.charAt(i + 1) == '\n') i++;
                } else currentField.append(c);
            }
        }
        if (!currentRow.isEmpty() || currentField.length() > 0) {
            currentRow.add(currentField.toString());
            rows.add(currentRow);
        }
        return rows;
    }

    private static String inventoryLookup(List<List<String>> inventory, String sku) {
        for (List<String> row : inventory) {
            if (row.size() >= 5 && row.get(0).equals(sku)) {
                Map<String, Object> res = new LinkedHashMap<>();
                res.put("sku", row.get(0));
                res.put("name", row.get(1));
                res.put("price_cents", Integer.parseInt(row.get(2)));
                res.put("currency", row.get(3));
                res.put("stock", Integer.parseInt(row.get(4)));
                return toJson(res);
            }
        }
        return "{\"error\":\"unknown sku: " + escapeJsonString(sku) + "\"}";
    }

    private static String convertCurrency(long amount, String from, String to, Map<String, Long> rates) {
        BigInteger X = BigInteger.valueOf(amount).multiply(Big            BigInteger.valueOf(rates.get(to)));
        BigInteger Y = BigInteger.valueOf(rates.get(from));
        BigInteger result = X.multiply(BigInteger.valueOf(2)).add(Y).divide(Y.multiply(BigInteger.valueOf(2)));
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("amount_cents", result.longValue());
        res.put("currency", to);
        return toJson(res);
    }

    private static String toJson(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Map) {
            Map<String, Object> map = (Map<String, Object>) obj;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> entry : map.entrySet()) {
                if (!first) sb.append(",");
                sb.append("\"").append(escapeJsonString(entry.getKey())).append("\":");
                sb.append(toJson(entry.getValue()));
                first = false;
            }
            return sb.append("}").toString();
        } else if (obj instanceof List) {
            List<Object> list = (List<Object>) obj;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(toJson(list.get(i)));
            }
            return sb.append("]").toString();
        } else if (obj instanceof String) {
            return "\"" + escapeJsonString((String) obj) + "\"";
        } else return String.valueOf(obj);
    }

    private static String escapeJsonString(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '"') sb.append("\\\"");
            else if (c == '\\') sb.append("\\\\");
            else if (c == '\b') sb.append("\\b");
            else if (c == '\f') sb.append("\\f");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else if (c < 32) sb.append(String.format("\\u%04x", (int) c));
            else sb.append(c);
        }
        return sb.toString();
    }

