                    let text = get_string_from_json(input_json, "text").unwrap_or_default();
                    let unit = get_string_from_json(input_json, "unit").unwrap_or_default();
                    measure(&text, &unit)
                }
                "reverse" => {
                    let text = get_string_from_json(input_json, "text").unwrap_or_default();
                    reverse(&text)
                }
                _ => Err(format!("unknown tool: {}", tool_name)),
            };
            tool_results.push((tool_id.clone(), tool_name.clone(), result));
        }
    }

    // Print request 1
    println!("request 1");
    for block in &blocks_s_order(&blocks_1) {
        print_block_output(block);
    }
    for (id, name, res) in &tool_results {
        match res {
            Ok(r) => println!("result {} {}", id, r),
            Err(e) => println!("error {} {}", id, e),
        }
    }

    // Construct request 2
    let user_msg_1 = format!(
        "{{\"role\": \"user\", \"content\": {}}}",
        prompt_q
    );
    let assistant_msg = format!(
        "{{\"role\": \"assistant\", \"content\": {}}}",
        blocks_to_json_array(&blocks_1)
    );
    let mut tool_content_parts = Vec::new();
    for (id, _, res) in &tool_results {
        let is_error = match res {
            Ok(_) => "false",
            Err(_) => "true",
        };
        // We need the result string. If it's an error, it's the error message.
        let res_str = match res {
            Ok(r) => r.clone(),
            Err(e) => e.clone(),
        };
        // But wait, the tool_result block needs the result string.
        // The tool_result block is: {"type": "tool_result", "tool_use_id": "...", "content": "...", "is_error": true/false}
        // We'll build this in the next step.
    }
    // Actually, the tool_result content is the result string.
    // Let's build the user_message_2 content.
    let mut user_msg_2_contents = Vec::new();
    for (id, _, res) in &tool_results {
        let is_error = match res {
            Ok(_) => "false",
            Err(_) => "true",
        };
        let res_str = match res {
            Ok(r) => r.clone(),
            Err(e) => e.clone(),
        };
        // Wait, the tool_result content is the result.
        // If it's an error, the content is the error message.
        // But we need to escape it for the JSON.
        // Let's just use a helper to create the tool_result JSON.
        let escaped_res = escape_json_string(&res_str);
        user_msg_2_contents.push(format!(
            "{{\"type\": \"tool_result\", \"tool_use_id\": \"{}\", \"content\": \"{}\", \"is_error\": {}}}",
            id, escaped_res, is_error
        ));
    }
    let user_msg_2 = format!(
        "{{\"role\": \"user\", \"content\": [{}]}}",
        user_msg_2_contents.join(",")
    );

    let request_body_2 = format!(
        "{{\"model\": {}, \"max_tokens\": {}, \"stream\": true, \"thinking\": {{\"type\": \"enabled\", \"budget_tokens\": {}}}, \"system\": {}, \"tools\": {}, \"messages\": [{}, {}, {}]}}",
        model_q, max_tokens, thinking_budget, system_q, tools_a, user_msg_1, assistant_msg, user_msg_2
    );

    let (transcript_2, usage_2, blocks_2) = run_request(host, &full_path, &api_key_q, &request_body_2);
    print_transcript_and_handle_error(&transcript_2);

    println!("request 2");
    for block in &blocks_s_order(&blocks_2) {
        print_block_output(block);
    }
    println!("usage input={} output={} cache_read={}", usage_1.0 + usage_2.0, usage_1.1 + usage_2.1, usage_1.2 + usage_2.2);
}

fn print_transcript_and_handle_error(transcript: &str) {
    if transcript.starts_with("ERROR") {
        let parts: Vec<&str> = transcript.splitn(4, ' ').collect();
        if parts.len() >= 4 {
            println!("ERROR {} {}: {}", parts[1], parts[2], parts[3]);
        }
        std::process::exit(0);
    }
}

fn escape_json_string(s: &str) -> String {
    let mut escaped = String::new();
    for c in s.chars() {
        match c {
            '\\' => escaped.push_e_slash('\\'),
            '"' => escaped.push_e_slash('"'),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            _ => escaped.push(c),
        }
    }
    escaped
}

trait PushESlash {
    fn push_e_slash(&mut self, c: char);
}
impl PushESlash for String {
    fn push_e_slash(&mut self, c: char) {
        self.push('\\');
        self.push(c);
    }
}

fn print_block_output(block: &Block) {
    match block.block_type.as_str() {
        "thinking" => {
            print!("thinking ");
            print_escaped_line(&block.thinking);
            print!("signature ");
            print_escaped_line(&block.signature);
        }
        "text" => {
            print!("text ");
            print_escaped_line(&block.text);
        }
        "tool_use" => {
            print!("tool_use {} {} ", block.id, block.name);
            print_escaped_line(&block.input_json);
        }
        _ => {}
    }
}

fn print_escaped_line(s: &str) {
    for c in s.chars() {
        match c {
            '\\' => print!("\\\\"),
            '\n' => print!("\\n"),
            '\r' => print!("\\r"),
            '\t' => print!("\\t"),
            _ => print!("{}", c),
        }
    }
    println!();
}

fn blocks_s_order(blocks: &BTreeMap<usize, Block>) -> Vec<Block> {
    blocks.values().cloned().collect()
}

fn blocks_to_json_array(blocks: &BTreeMap<usize, Block>) -> String {
    let mut parts = Vec::new();
    for block in blocks.values() {
        match block.block_type.as_str() {
            "thinking" => {
                parts.push(format!(
                    "{{\"type\": \"thinking\", \"thinking\": {}, \"signature\": {}}}",
                    escape_json_string(&block.thinking),
                    escape_json_string(&block.signature)
                ));
            }
            "text" => {
                parts.push(format!(
                    "{{\"type\": \"text\", \"text\": {}}}",
                    escape_json_string(&block.text)
                ));
            }
            "tool_use" => {
                parts.push(format!(
                    "{{\"type\": \"tool_use\", \"id\": \"{}\", \"name\": \"{}\", \"input\": {}}}",
                    block.id, block.name, block.input_json
                ));
            }
            _ => {}
        }
    }
    format!("[{}]", parts.join(","))
}

fn run_request(host: &str, path: &str, api_key: &str, body: &str) -> (String, (f64, f64, f64), BTreeMap<usize, Block>) {
    let mut stream = TcpStream::connect(host).unwrap();
    let request = format!(
        "POST {} HTTP/1.1\r\n\
         Host: {}\r\n\
         x-api-key: {}\r\n\
         anthropic-version: 2023-06-01\r\n\
         content-type: application/json\r\n\
         content-length: {}\r\n\
         \r\n\
         {}",
        path, host, api_key, body.len(), body
    );
    stream.write_all(request.as_bytes()).unwrap();

    let mut response_buffer = Vec::new();
    let mut chunk = [0u8; 8192];
    loop {
        let n = stream.read(&mut chunk).unwrap();
        if n == 0 { break; }
        response_buffer.extend_from_slice(&chunk[..n]);
    }

    let response_str = String::from_utf8_lossy(&response_buffer);
    let mut lines = response_str.split("\r\n\r\n");
    let header_part = lines.next().unwrap_or("");
    let body_part = lines.next().unwrap_or("");

    // Parse status
    let status_line = header_part.split("\r\n").next().unwrap_or("");
    let status_code = status_line.split_whitespace().nth(1).unwrap_or("200");

    if status_code != "200" {
        return (format!("ERROR {} {}", status_code, body_part), (0.0, 0.0, 0.0), BTreeMap::new());
    }

    let mut transcript = String::new();
    let mut usage = (0.0, 0.0, 0.0);
    let mut blocks: BTreeMap<usize, Block> = BTreeMap::new();

    // SSE parsing
    let mut current_event = String::new();
    let mut current_data = String::new();

    // The body_part is the SSE stream.
    let mut sse_lines = body_part.split("\n");

    // We need to handle the case where the body is split across lines.
    // Let's use a more robust way to split the body.
    let mut sse_content = body_part.to_string();

    // Since the connection closes, we can just use the body_part.
    // But we must handle the case where the body might be in a different encoding.
    // The problem says it's UTF-8.

    let mut lines_iter = sse_content.split("\n");
    let mut current_event = String::new();
    let mut current_data = String::new();

    while let Some(line) = lines_iter.next() {
        let line = line.trim_end_matches("\r");
        if line.is_empty() {
            if !current_data.is_empty() {
                // Process event
                let event_res = process_event(&current_data, &mut usage, &mut blocks, &mut transcript);
                if event_res.starts_with("ERROR") {
                    return (event_res, (0.0, 0.0, 0.0), BTreeMap::new());
                }
            }
            current_data.clear();
            current_event.clear();
            continue;
        }
        if line.starts_with("event: ") {
            current_event = line[7..].to_string();
        } else if line.starts_with("data: ") {
            current_data = line[6..].to_string();
        } else if line.starts_with(':') {
            // comment
        } else {
            // Some systems use "data:" instead of "data: "
            if line.starts_with("data:") {
                current_data = line[4..].trim_start().to_string();
            }
        }

        // If it's a data line and not an empty line, we might need to accumulate.
        // But the rule is: "a blank line ends the event."
    }

    // The loop above might not process the last event if there's no blank line.
    if !current_data.is_empty() {
        let event_res = process_event(&current_data, &mut usage, &mut blocks, &mut transcript);
        if event_res.starts_with("ERROR") {
            return (event_res, (0.0, 0.0, 0.0), BTreeMap::new());
        }
    }

    (transcript, usage, blocks)
}

