import Foundation

func escapeJSON(_ s: String) -> String {
    var escaped = ""
    for char in s {
        let utf16 = char.unicodeScalars.first!.value
        if utf16 == 34 { escaped += "\\\"" }
        else if utf16 == 92 { escaped += "\\\\" }
        else if utf16 == 8 { escaped += "\\b" }
        else if utf16 == 12 { escaped += "\\f" }
        else if utf16 == 10 { escaped += "\\n" }
        else if utf16 == 13 { escaped += "\\r" }
        else if utf16 == 9 { escaped += "\\t" }
        else if utf16 < 32 { escaped += String(format: "\\u%04x", UInt32(utf16)) }
        else { escaped += String(char) }
    }
    return escaped
}

func parseCSV(text: String) -> [[String]] {
    var rows: [[String]] = []
    var currentRow: [String] = []
    var currentField = ""
    var inQuotes = false
    var i = text.startIndex
    while i < text.endIndex {
        let char = text[i]
        if inQuotes {
            if char == "\"" {
                if i + 1 < text.endIndex && text[i+1] == "\"" {
                    currentField.append("\""); i = text.index(after: i)
                } else { inQuotes = false }
            } else { currentField.append(char) }
        } else {
            if char == "\"" { inQuotes = true }
            else if char == "," { currentRow.append(currentField); currentField = "" }
            else if char == "\r" || char == "\n" {
                currentRow.append(currentField); rows.append(currentRow); currentRow = []; currentField = ""
                if char == "\r" && i + 1 < text.endIndex && text[i+1] == "\n" { i = text.index(after: i) }
            } else { currentField.append(char) }
        }
        i = text.index(after: i)
    }
    if text.count > 0 && !(text.last! == "\n" || text.last! == "\r") {
        currentRow.append(currentField); rows.append(currentRow)
    }
    return rows
}

func main() {
    let args = CommandLine.arguments
    if args.count < 3 { return }
    let dataDir = args[1], baseUrl = args[2]
    let taskPath = "\(dataDir)/task.json", inventoryPath = "\(dataDir)/inventory.csv", ratesPath = "\(dataDir)/rates.json"

