          let inventoryData = try? Data(contentsOf: URL(fileURLWithPath: inventoryPath)),
          let ratesData = try? Data(contentsOf: URL(fileURLWithPath: ratesPath)) else { return }

    var inventoryText = String(data: inventoryData, encoding: .utf8) ?? ""
    if inventoryText.hasPrefix("\u{FEFF}") { inventoryText.removeFirst() }
    let inventoryRows = parseCSV(text: inventoryText)

    var ratesDict: [String: Int64] = [:]
    if let ratesJSON = try? JSONSerialization.jsonObject(with: ratesData) as? [String: Any],
       let rates = ratesJSON["rates"] as? [String: Int64] {
