        ["role": "system", "content": system],
        ["role": "user", "content": user]
    ]

    var totalPrompt = 0, totalCompletion = 0, totalTokens = 0, totalRequests = 0
    let url = URL(string: "\(baseUrl)/chat/completions")!

    while true {
        totalRequests += 1
        var body: [String: Any] = ["model": model, "messages": messages, "tools": tools, "tool_choice": "auto"]
        let bodyData = try! JSONSerialization.data(withJSONObject: body, options: [])

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("Bearer \(api_key)", forHTTPHeaderField: "Authorization")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = bodyData

        let semaphore = DispatchSemaphore(value: 0)
        var responseData: Data?
        var responseStatus: Int = 0
        var errorMsg = ""

        let task = URLSession.shared.dataTask(with: request) { data, res, err in
            responseData = data
            if let httpResponse = res as? HTTPURLResponse { responseStatus = httpResponse.statusCode }
            if let err = err { errorMsg = err.localizedDescription }
            semaphore.signal()
        }
        task.resume()
        semaphore.wait()

        if responseStatus != 200 {
            let errorBody = try? JSONSerialization.jsonObject(with: responseData ?? Data()) as? [String: Any]
            let message = (errorBody?["error"] as? [String: Any])?["message"] as? String ?? errorMsg
            print("ERROR \(responseStatus) \(message)")
            exit(0)
        }

        let response = try! JSONSerialization.jsonObject(with: responseData!) as! [String: Any]
        let choices = response["choices"] as! [[String: Any]]
        let message = choices[0]["message"] as! [String: Any]
        let finishReason = choices[0]["finish_reason"] as? String

        // Update usage
        if let usage = response["usage"] as? [String: Int] {
            totalPrompt += usage["prompt_tokens"] ?? 0
            totalCompletion += usage["completion_tokens"] ?? 0
            totalTokens += usage["total_tokens"] ?? 0
        }

        if finishReason == "stop" {
            let content = message["content"] as? String ?? ""
            print("FINAL \(content)")
            print("USAGE prompt=\(totalPrompt) completion=\(totalCompletion) total=\(totalTokens) requests=\(totalRequests)")
            exit(0)
        } else if finishReason == "tool_calls" {
            if let content = message["content"] as? String { print("SAY \(content)") }

            // Append assistant message to conversation
            messages.append(message)

            let toolCalls = message["tool_calls"] as? [[String: Any]] ?? []
            for toolCall in toolCalls {
                let id = toolCall["id"] as! String
                let name = toolCall["function"]?["name"] as! String
                let argsString = toolCall["function"]?["arguments"] as! String
                let args = (try? JSONSerialization.jsonObject(with: argsString.data(using: .utf8)!)) as? [String: Any] ?? [:]

                print("CALL \(id) \(name)")

