                            let nameVal = row.count > 1 ? row[1] : ""
                            let priceVal = row.count > 2 ? row[2] : "0"
                            let currencyVal = row.count > 3 ? row[3] : ""
                            let stockVal = row.count > 4 ? row[4] : "0"
                            resultStr = "{\"sku\":\"\(escapeJSON(sku))\",\"name\":\"\(escapeJSON(nameVal))\",\"price_cents\":\(priceVal),\"currency\":\"\(escapeJSON(currencyVal))\",\"stock\":\(stockVal)}"
                            found = true; break
                        }
}
                    if !found { resultStr = "{\"error\":\"unknown sku: \(escapeJSON(sku))\"}" }
                } else if name == "convert_currency" {
                    let amount = Int64(args["amount_cents"] as? Int ?? 0)
                    let from = args["from"] as? String ?? ""
                    let to = args["to"] as? String ?? ""
                    let rFrom = ratesDict[from] ?? 1
                    let rTo = ratesDict[to] ?? 1
                    let converted = (2 * amount * rTo + rFrom) / (2 * rFrom)
                    resultStr = "{\"amount_cents\":\(converted),\"currency\":\"\(escapeJSON(to))\"}"
                } else {
                    let argName = name
                    resultStr = "{\"error\":\"unknown tool: \(escape[argName]\"
                }
                // Wait, error formatting for tool name
            }
        }
    }
}

