fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        return;
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    let mut task_json = std::fs::read_to_string(format!("{}/task.json", data_dir)).unwrap();
    // Remove potential BOM
    if task_json.starts_with('\u{FEFF}') {
        task_json = task_json.trim_start_matches('\u{FEFF}').to_string();
    }
    let mut inventory_contents = std::fs::read_to_string(format!("{}/inventory.csv", data_dir)).unwrap();
    if inventory_contents.starts_with('\u{FEFF}') {
        inventory_contents = inventory_contents.trim_start_matches('\u{FEFF}').to_string();
    }
    let rates_json = std::fs::read_to_string(format!("{}/rates.json", data_dir)).unwrap();

    let api_key = get_json_string(&task_json, "api_key");
    let model = get_json_string(&task_json, "model");
    let system = get_json_string(&task_json, "system");
    let user = get_json_string(&task_json, "user");

    let tools_idx = task_json.find("\"tools\":").unwrap();
    let tools_start = task_json[tools_idx..].find('[').unwrap() + tools_idx;
    let tools_end = task_json.rfind(']').unwrap() + 1;
    let tools_json = &task_json[tools_start..tools_end];

    let inventory_rows = parse_csv(&inventory_contents);
    let rates_map = parse_rates(&rates_json);

    let mut messages = vec![
        format!(r#"{{"role":"system","content":{}}}"#, json_string_literal(&system)),
        format!(r#"{{"role":"user","content":{}}}"#, json_string_literal(&user)),
    ];

    let mut total_prompt = 0;
    let mut total_completion = 0;
    let mut total_tokens = 0;
    let mut request_count = 0;

    loop {
        request_count += 1;
        let body = format!(
            r#"{{"model":{},"messages":[{}],"tools":{},"tool_choice":"auto"}}"#,
            json_string_literal(&model),
            messages.join(","),
            tools_json
        );

        let (status, response_body) = send_request(base_url, &api_key, &body);
        if status != 200 {
            let error_msg = get_error_message(&response_body);
            println!("ERROR {} {}", status, error_msg);
            return;
        }

        let mut parser = Parser::new(&response_body);
        let root = parser.parse();

        let finish_reason = get_finish_reason(&root);
        let content = get_content(&root);

        if finish_reason == "stop" {
            if !content.is_empty() {
                println!("SAY {}", content);
            }
            println!("FINAL {}", content);
            println!("USAGE prompt={} completion={} total={} requests={}", total_prompt, total_completion, total_tokens, request_count);
            break;
        } else if finish_reason == "tool_calls" {
            if !content.is_empty() {
                println!("SAY {}", content);
            }
            let tool_calls = get_tool_calls(&root);
            for tc in &tool_calls {
                println!("CALL {} {}", tc.id, tc.name);
            }

            // Add assistant message to conversation
            messages.push(format!(r#"{{"role":"assistant","content":{},"tool_calls":{}}}"#, 
                if content.is_empty() { "null".to_string() } else { json_string_literal(&content) },
                format_tool_calls_json(&tool_calls)
            ));

            for tc in tool_calls {
                let result = execute_tool(&tc.name, &tc.arguments, &inventory_rows, &rates_map);
                println!("RESULT {} {}", tc.id, result);
                messages.push(format!(r#"{{"role":"tool","tool_call_id":"{}","content":{}}}"#, 
                    json_escape(&tc.id), json_string_literal(&result)));
            }
        }

        let (p, c, t) = get_usage(&root);
        total_prompt += p;
        total_completion += c;
        total_tokens += t;
    }
}

fn json_string_literal(s: &str) -> String {
    format!("\"{}\"", json_escape(s))
}

fn json_escape(s: &str) -> String {
    let mut res = String::new();
    for c in s.chars() {
        match c {
            '"' => res.push_str("\\\""),
            '\\' => res.push_str("\\\\"),
            '\u{0008}' => res.push_str("\\b"),
            '\u{000C}' => res.push_str("\\f"),
            '\u{000A}' => res.push_str("\\n"),
            '\u{000D}' => res.push_str("\\r"),
            '\u{0009}' => res.push_str("\\t"),
            c if c.is_ascii_control() => {
                res.push_str(&format!("\\u{:04x}", c as u32));
            }
            _ => res.push(c),
        }
    }
    res
}

fn get_json_string(json: &str, key: &str) -> String {
    let key_pattern = format!("\"{}\":", key);
    if let Some(start_idx) = json.find(&key_pattern) {
        let after_key = &json[start_idx + key_pattern.len()..];
        let mut after_key = afterskip_whitespace(after_key);
        if after_key.starts_with('"') {
            let mut end_idx = 1;
            let bytes = after_key.as_bytes();
            while end_idx < bytes.len() {
                if bytes[end_idx] == b'"' {
                    let mut escaped = false;
                    let mut i = end_idx - 1;
                    while i > 0 && bytes[i] == b'\\' {
                        escaped = !escaped;
                        i -= 1;
                    }
                    if !escaped { break; }
                }
                end_idx += 1;
            }
            return after_key[1..end_idx].to_string();
        }
    }
    String::new()
}

fn afterskip_whitespace(s: &str) -> &str {
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    &s[i..]
