fn parse_csv_robust(data: &str) -> Vec<Vec<String>> {
    let mut rows = Vec::new();
    let mut current_row = Vec::new();
    let mut current_field = String::new();
    let mut in_quotes = false;
    let bytes = data.as_bytes();
    let mut i = 0;

    while i < bytes.len() {
        let b = bytes[i] as char;
        if in_quotes {
            if b == '"' {
                if i + 1 < bytes.len() && bytes[i + 1] as char == '"' {
                    current_field.push('"');
                    i += 1;
                } else {
                    in_quotes = false;
                }
            } else {
                current_field.push(b);
            }
        } else {
            if b == '"' {
                in_quotes = true;
            } else if b == ',' {
                current_row.push(current_field.clone());
                current_field.clear();
            } else if b == '\r' || b == '\n' {
                if !current_field.is_empty() || !current_row.is_empty() {
                    current_row.push(current_field.clone());
                    rows.push(current_row.clone());
                    current_row.clear();
                    current_field.clear();
                }
                if b == '\r' && i + 1 < bytes.len() && bytes[i+1] as char == '\n' {
                    i += 1;
                }
            } else {
                current_field.push(b);
            }
        }
        i += 1;
    }
    if !current_field.is_empty() || !current_row.is_empty() {
        current_row.push(current_field);
        rows.push(current_row);
    }
    if !rows.is_empty() && rows[0].len() == 1 && rows[0][0].is_empty() { rows.remove(0); }
    rows
}

