fn parse_rates(json: &str) -> HashMap<String, i64> {
    let mut map = HashMap::new();
    let mut parser = Parser::new(json);
    let root = parser.parse();
    if let Value::Object(ref map_obj) = root {
        if let Some(Value::Object(ref rates_obj)) = map_obj.get("rates") {
            for (k, v) in rates_obj {
                if let Value::Number(n) = v {
                    map.insert(k.clone(), *n);
                }
            }
        }
    }
    map
}

fn execute_tool(name: &str, args_json: &str, inventory: &Vec<Vec<String>>, rates: &HashMap<String, i64>) -> String {
    let mut parser = Parser::new(args_json);
    let args_obj = parser.parse();

    match name {
        "inventory_lookup" => {
            let sku = if let Value::Object(ref m) = args_obj {
                if let Some(Value::String(s)) = m.get("sku") { s.clone() } else { "".to_string() }
            } else { "".to_string() };

            for row in inventory.iter().skip(1) {
                if !row.is_empty() && row[0] == sku {
                    return format!(r#"{{"sku":"{}","name":"{}","price_cents":{},"currency":"{}","stock":{}}}"#,
                        json_escape(&row[0]), json_escape(&row[1]), row[2].parse::<i64>().unwrap_or(0), json_escape(&row[3]), row[4].parse::<i64>().unwrap_or(0));
                }
            }
            format!(r#"{{"error":"unknown sku: {}"}}"#, json_escape(&sku))
        }
        "convert_currency" => {
            let amount = if let Value::Object(ref m) = args_obj {
                if let Some(Value::Number(n)) = m.get("amount_cents") { *n } else { 0 }
            } else { 0 };
            let from = if let Value::Object(ref m) = args_obj {
                if let Some(Value::String(s)) = m.get("from") { s.clone() } else { "".to_string() }
            } else { "".to_string() };
            let to = if let Value::Object(ref m) = args_obj {
                if let Some(Value::String(s)) = m.get("to") { s.clone() } else { "".to_string() }
            } else { "".to_string() };

            let r_from = *rates.get(&from).unwrap_or(&1);
            let r_to = *rates.get(&to).unwrap_or(&1);

            let converted = (2 * amount * r_to + r_from) / (2 * r_from);
            format!(r#"{{"amount_cents":{},"currency":"{}"}}"#, converted, json_escape(&to))
        }
        _ => format!(r#"{{"error":"unknown tool: {}"}}"#, json_escape(name)),
    }
}

fn send_request(url: &str, api_key: &str, body: &str) -> (u16, String) {
    let host = url.split('/').nth(2).unwrap_or("").split(':').next().unwrap_or("");
    let port = url.split(':').nth(1).and_then(|s| s.split('/').next()).unwrap_or("").parse::<u16>().unwrap_or(80);
    // The above is a bit brittle. Let's use a more direct approach.
    let parts: Vec<&str> = url.split('/').collect();
    let host_port = parts[2];
    let host = host_port.split(':').next().unwrap();
    let port = host_port.split(':').nth(1).unwrap_or("80");

    let mut stream = TcpStream::connect(format!("{}:{}", host, port)).unwrap();
    let request = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nAuthorization: Bearer {}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        parts[3], host_port, api_key, body.len(), body
    );
    stream.write_all(request.as_bytes()).unwrap();

    let mut response = String::new();
    let mut buffer = [0; 8192];
    let mut total_len = 0;
    loop {
        let n = match stream.read(&mut buffer) {
            Ok(0) => break,
            Ok(n) => n,
            _ => break,
        };
        if n == 0 { break; }
        let chunk = String::from_utf8_lossy(&buffer[..n]);
        response.push_str(&chunk);
        total_len += n;
    }

    let lines: Vec<&str> = response.splitn(2, "\r\n\r\n").collect();
    let header = lines[0];
    let body = if lines.len() > 1 { lines[1].to_string() } else { "".to_string() };

    let status_line = header.lines().next().unwrap_or("");
    let status = status_line.split_whitespace().nth(1).and_then(|s| s.parse::<u16>().ok()).unwrap_or(0);

    (status, body)
}

fn get_error_message(body: &str) -> String {
    let mut parser = Parser::new(body);
