fn get_tool_calls(root: &Value) -> Vec<ToolCall> {
    let mut calls = Vec::new();
    if let Value::Object(ref m) = root {
        if let Some(Value::Array(a)) = m.get("choices").and_then(|v| {
            if let Value::Array(a) = v { Some(a) } else { None }
        }) {
            if let Some(choice) = a.get(0) {
                if let Value::Object(ref c_obj) = choice {
                    if let Some(Value::Array(tc_list)) = c_obj.get("tool_calls") {
                        for tc in tc_list {
                            if let Value::Object(ref tc_obj) = tc {
                                let id = if let Some(Value::String(s)) = tc_obj.get("id") { s.clone() } else { "".to_string() };
                                let name = if let Some(Value::Object(ref f)) = tc_obj.get("function") {
                                    if let Some(Value::String(s)) = f.get("name") { s.clone() } else { "".to_string() }
                                } else { "".to_string() };
                                let args = if let Some(Value::Object(ref f)) = tc_obj.get("function") {
                                    if let Some(Value::String(s)) = f.get("arguments") { s.clone() } else { "".to_string() }
                                } else { "".to_string() };
                                calls.push(ToolCall { id, name, arguments: args });
                            }
                        }
                    }
                }
            }
        }
    }
    calls
}

