    const match = s.match(/^([+-]?\d+)(:(\d{2})(:(\d{2}))?)?$/);
    if (!match) return 0n;
    const sign = s.startsWith('-') ? -1n : 1n;
    const abs_s = s.startsWith('-') ? s.slice(1) : (s.startsWith('+') ? s.slice(1) : s);
    const abs_match = abs_s.match(/^(\d+)(:(\d{2})(:(\d{2}))?)?$/);
