            if let range = self.buffer.range(of: Data([0x0D, 0x0A, 0x0D, 0x0A])) {
                let headerString = String(data: self.buffer.subdata(in: 0..<range.upperBound), encoding: .utf8) ?? ""
                let lines = headerString.components(separatedBy: "\r\n")
                if lines.isEmpty { return }

                let statusLine = lines[0]
                let statusParts = statusLine.split(separator: " ", maxSplits: 1)
                let code = statusParts.isEmpty ? "" : String(statusParts[0])
                let reason = statusParts.count > 1 ? String(statusParts[1]) : ""

                if code != "101" {
                    print("handshake failed: \(code) \(reason)")
                    self.connection.cancel()
                    self.dispatchGroup.leave()
                    return
                }

                var acceptHeader: String?
                for line in lines {
                    if line.lowercased().hasPrefix("sec-websocket-accept:") {
                        acceptHeader = line.split(separator: ":", maxSplits: 1).last?.trimmingCharacters(in: .whitespaces)
                        break
                    }
                }

                let expectedKey = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
                let expectedAccept = Data(expectedKey.utf8).sha1().base64EncodedString()

                if acceptHeader == nil || acceptHeader != expectedAccept {
                    print("handshake failed: bad Sec-WebSocket-Accept")
                    self.connection.cancel()
                    self.dispatchGroup.leave()
                    return
                }

                self.buffer.removeSubrange(0..<range.upperBound)
                self.receiveLoop()
            } else {
                self.receiveHandshakeResponse(key: key)
            }
        }
    }

    private func receiveLoop() {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 65536) { [weak self] data, _, _, error in
            guard let self = self else { return }
            if let data = data, !data.isEmpty {
                self.buffer.append(data)
                self.processBuffer()
            }
            if error == nil {
                self.receiveLoop()
            } else {
                self.dispatchGroup.leave()
            }
        }
    }

    private func processBuffer() {
        while buffer.count >= 2 {
            let firstByte = buffer[0]
            let secondByte = buffer[1]
            let fin = (firstByte & 0x80) != 0
            let opcode = firstByte & 0x0F
            let lenIndicator = secondByte & 0x7F

            var headerSize = 2
            var payloadLen: UInt64 = 0

            if lenIndicator < 126 {
                payloadLen = UInt64(lenIndicator)
                headerSize = 2
            } else if lenIndicator == 126 {
                if buffer.count < 4 { break }
                payloadLen = UInt64(buffer[2]) << 8 | UInt64(buffer[3])
                headerSize = 4
            } else {
                if buffer.count < 10 { break }
                payloadLen = 0
                for i in 0..<8 {
                    payloadLen |= UInt64(buffer[2 + i]) << (8 * (7 - i))
                }
                headerSize = 10
            }

            if buffer.count < headerSize + Int(payloadLen) {
                break 
            }

            let framePayload = buffer.subdata(in: headerSize..<(headerSize + Int(payloadLen)))
            buffer.removeSubrange(0..<headerSize + Int(payloadLen))

            if opcode == 0 { // Continuation
                if isAwaitingSHA1 {
                    messageBuffer.append(framePayload)
                    if fin {
                        processSHA1(messageBuffer)
                        messageBuffer.removeAll()
                        isAwaitingSHA1 = false
                    }
                } else {
                    messageBuffer.append(framePayload)
                    if fin {
                        processCommand(messageBuffer, opcode: 0)
                        messageBuffer.removeAll()
                    }
                }
            } else if opcode == 1 || opcode == 2 { // Text or Binary
                if isAwaitingSHA1 {
                    messageBuffer.append(framePayload)
                    if fin {
                        processSHA1(messageBuffer)
                        messageBuffer.removeAll()
                        isAwaitingSHA1 = false
                    }
                } else {
                    if fin {
                        processCommand(framePayload, opcode: opcode)
                    } else {
                        messageBuffer.append(framePayload)
                    }
                }
            } else if opcode == 9 { // Ping
                sendPong(framePayload)
            } else if opcode == 10 { // Pong
                // Ignore
            } else if opcode == 8 { // Close
                handleClose(framePayload)
            }
        }
    }

    private func processCommand(_ payload: Data, opcode: UInt8) {
        guard let text = String(data: payload, encoding: .utf8) else { return }

        if text.hasPrefix("ADD ") {
            let parts = text.split(separator: " ", maxSplits: 2)
            if parts.count == 3 {
                let a = Int64(parts[1]) ?? 0
                let b = Int64(parts[2]) ?? 0
                let sum = a + b
                print("\(text) -> \(sum)")
            }
        } else if text.hasPrefix("REV ") {
            let textToReverse = String(text.dropFirst(4))
            let reversed = String(textToReverse.reversed())
            print("\(text) -> \(reversed)")
        } else if text == "SHA1" {
            isAwaitingSHA1 = true
        } else if text == "BYE" {
            sendCloseFrame(status: 1000)
        }
    }

    private func processSHA1(_ payload: Data) {
        let hex = payload.sha1().map { String(format: "%02x", $0) }.joined()
        print("SHA1 \(payload.count) -> \(hex)")
    }

    private func sendPong(_ payload: Data) {
        sendMaskedFrame(opcode: 10, payload: payload)
    }

    private func sendCloseFrame(status: UInt16) {
        var payload = Data()
        payload.append(UInt8((status >> 8) & 0xFF))
        payload.append(UInt8(status & 0xFF))
        sendMaskedFrame(opcode: 8, payload: payload)
    }

    private func sendMaskedFrame(opcode: UInt8, payload: Data) {
        var frame = Data()
        frame.append(0x80 | (opcode & 0x0F))

        if payload.count < 126 {
            frame.append(UInt8(payload.count) | 0x80)
        } else if payload.count < 65536 {
            frame.append(126 | 0x80)
            frame.append(UInt8((payload.count >> 8) & 0xFF))
            frame.append(UInt8(payload.count & 0xFF))
        } else {
            frame.append(127 | 0x80)
            for i in (0..<8).reversed() {
                frame.append(UInt8((UInt64(payload.count) >> (i * 8)) & 0xFF))
            }
        }

        var maskKey = [UInt8](repeating: 0, count: 4)
        _ = SecRandomCopyBytes(kSecRandomDefault, 4, &maskKey)
        frame.append(contentsOf: maskKey)

        var maskedPayload = Data()
        for i in 0..<payload.count {
            maskedPayload.append(payload[i] ^ maskKey[i % 4])
        }
        frame.append(maskedPayload)

        connection.send(content: frame, completion: .contentProcessed({ _ in }))
    }

    private func handleClose(_ payload: Data) {
        var code: UInt16 = 0
        var reason = ""
        if payload.count >= 2 {
            code = UInt16(payload[0]) << 8 | UIntlet(payload[1]) // typo
            // ...
        }
    }
